  "<strong>Folgen des Widerrufs</strong><br> Wenn du diesen Vertrag widerrufst, haben wir dir alle Zahlungen, die wir von dir erhalten haben, unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurückzuzahlen, an dem die Mitteilung über deinen Widerruf dieses Vertrags bei uns eingegangen ist. Für diese Rückzahlung verwenden wir dasselbe Zahlungsmittel, das du bei der ursprünglichen Transaktion eingesetzt hast, es sei denn, mit dir wurde ausdrücklich etwas anderes vereinbart; in keinem Fall werden dir wegen dieser Rückzahlung Entgelte berechnet.": "<strong>Effects of Withdrawal</strong><br> If you withdraw from this contract, we shall reimburse to you all payments received from you without undue delay and in any event not later than fourteen days from the day on which we are informed about your decision to withdraw from this contract. We will carry out such reimbursement using the same means of payment as you used for the initial transaction, unless you have expressly agreed otherwise; in any event, you will not incur any fees as a result of such reimbursement.",
  "<strong>Gold</strong> ist die Spielwährung von Emberwrath. Gekauftes Gold wird dem Charakter gutgeschrieben, den du beim Kauf auswählst. Es lässt sich nicht auf andere Charaktere oder Konten übertragen.": "<strong>Gold</strong> is the in-game currency of Emberwrath. Purchased Gold is credited to the character you select at purchase. It cannot be transferred to other characters or accounts.",
  "<strong>Vorzeitiges Erlöschen</strong><br> Das Widerrufsrecht erlischt bei einem Vertrag über digitale Inhalte, die nicht auf einem körperlichen Datenträger geliefert werden, wenn wir mit der Bereitstellung begonnen haben, nachdem du ausdrücklich zugestimmt hast, dass wir vor Ablauf der Widerrufsfrist mit der Bereitstellung beginnen, du deine Kenntnis davon bestätigt hast, dass du durch deine Zustimmung mit Beginn der Bereitstellung dein Widerrufsrecht verlierst, und wir dir eine Bestätigung des Vertrags auf einem dauerhaften Datenträger (E&#8209;Mail) zur Verfügung gestellt haben.": "<strong>Early Expiry</strong><br> For a contract for the supply of digital content not supplied on a tangible medium, the right of withdrawal expires if we have begun the supply after you have expressly consented to our beginning the supply before the end of the withdrawal period, you have acknowledged that by giving your consent you lose your right of withdrawal once the supply begins, and we have provided you with a confirmation of the contract on a durable medium (email).",
  "<strong>Widerrufsrecht</strong><br> Du hast das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag des Vertragsabschlusses.": "<strong>Right of Withdrawal</strong><br> You have the right to withdraw from this contract within fourteen days without giving any reason. The withdrawal period will expire after fourteen days from the day of the conclusion of the contract.",
