  "Alle": "All",
  "Alle Fähigkeiten laden 4 % schneller je Rang.": "All skills recharge 4% faster per rank.",
  "Alle Kamele, alle Ballen, alle Treiber. Ich glaube, das ist das erste Mal.": "Every camel, every bale, every drover. I think that's a first.",
  "Alle Materialien einlagern": "Store All Materials",
  "Alle Preise sind Endpreise in Euro einschließlich Umsatzsteuer. Weitere Kosten fallen nicht an. Du bezahlst über Stripe mit den dort angebotenen Zahlungsarten, zum Beispiel Karte, PayPal, Apple Pay oder Google Pay. Der Betrag wird sofort fällig.": "All prices are final prices in euros including VAT. There are no additional costs. You pay via Stripe with the payment methods offered there, for example card, PayPal, Apple Pay or Google Pay. The amount is due immediately.",
  "Alle Preise sind Endpreise inklusive Umsatzsteuer.": "All prices are final prices including VAT.",
  "Alle Preise sind Endpreise. Nach § 19 UStG wird keine Umsatzsteuer berechnet.": "All prices are final prices. No VAT is charged under § 19 UStG (German small business regulation).",
  "Alle wegwerfen": "Discard All",
  "alles": "all",
  "Alles gut?": "All good?",
  "Alles hat seinen Preis. Auch Ratschläge. Der hier ist umsonst: kauf Tränke.": "Everything has its price. Even advice. This one's free: buy potions.",
  "Alles, was du brauchst, für einen Preis, den du nicht magst.": "Everything you need, at a price you won't like.",
  "Alles, was du brauchst, für einen Preis, den du nicht magst. So ist die Steppe.": "Everything you need, at a price you won't like. That's the Steppe.",
  "Als „{0}“ gespeichert.": "Saved as “{0}”.",
  "Als der Glutfall die Senke traf, veränderte er manche Familien für immer: aschgraue Haut, Hörner und Adern, in denen Glut glimmt. Ihre Fähigkeiten brennen heißer.": "When the Emberfall struck the Hollow, it changed some families forever: ash-gray skin, horns and veins in which embers smolder. Their skills burn hotter.",
  "Als die Banditen kamen, habe ich meine Kräutertasche fallen lassen. Irgendwo im Südwesten des Waldes, nahe dem alten Pfad. Ohne sie kann ich kaum etwas brauen.": "When the bandits came, I dropped my herb satchel. Somewhere in the southwest of the forest, near the old path. Without it I can barely brew a thing.",
  "Als Verbraucher hast du ein gesetzliches Widerrufsrecht. Weil wir Gold und Designs sofort bereitstellen, erlischt es, sobald wir mit der Bereitstellung beginnen, wenn du vorher ausdrücklich zugestimmt hast, dass wir vor Ablauf der Widerrufsfrist beginnen, du bestätigt hast, dass du damit dein Widerrufsrecht verlierst, und wir dir die Bestellbestätigung geschickt haben. Diese Zustimmung holen wir vor jedem Kauf mit einem Häkchen ein. Ohne Häkchen ist kein Kauf möglich.": "As a consumer, you have a statutory right of withdrawal. Because we provide Gold and cosmetics immediately, it expires as soon as we begin providing them, if you have previously expressly agreed that we may begin before the withdrawal period ends, you have confirmed that you thereby lose your right of withdrawal, and we have sent you the order confirmation. We obtain this consent with a checkbox before every purchase. Without the checkbox, no purchase is possible.",
  "Alt, gelb und kalt wie Stein.": "Old, yellow and cold as stone.",
  "Alte Eiche": "Old Oak",
  "Alte Glutkäferhöhle": "Old Ember Beetle Cave",
  "Alte Schlackenminen": "Old Slag Mines",
  "Älter als das Dorf, sagen die Jäger. Sein Fell ist grau vor Asche und Jahren.": "Older than the village, the hunters say. His fur is gray with ash and years.",
