  "An diese Adresse darf der Server noch keine E-Mails schicken. Solange kein eigener Mailversand eingerichtet ist, geht das nur an die E-Mail deines Supabase-Kontos.": "The server can't send email to this address yet. Until a dedicated mail service is set up, email can only go to the address of your Supabase account.",
  "An Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Deutschland, E&#8209;Mail support@emberwrath.com:": "To Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Germany, email support@emberwrath.com:",
  "An Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Deutschland, E&#8209;Mail support@emberwrath.com:<br> Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über die Bereitstellung der folgenden digitalen Inhalte (*):<br> Bestellt am (*):<br> Name des/der Verbraucher(s):<br> Anschrift des/der Verbraucher(s):<br> Unterschrift des/der Verbraucher(s) (nur bei Mitteilung auf Papier):<br> Datum:<br> (*) Unzutreffendes streichen.": "To Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Germany, email support@emberwrath.com:<br> I/We (*) hereby give notice that I/We (*) withdraw from my/our (*) contract for the supply of the following digital content (*):<br> Ordered on (*):<br> Name of consumer(s):<br> Address of consumer(s):<br> Signature of consumer(s) (only if this form is notified on paper):<br> Date:<br> (*) Delete as appropriate.",
