  "Atme flach. Die Sporen sind heute gierig.": "Breathe shallow. The spores are hungry today.",
  "Auf dem Siegel glüht eine Krone aus Flammen.": "A crown of flames glows on the seal.",
  "Auf den Stegen ist es ruhig. Ich habe drei Händler gesehen, die heute lebend angekommen sind. Ein Rekord. Nimm das, du hast es verdient.": "It's quiet on the boardwalks. I saw three traders arrive alive today. A record. Take this, you've earned it.",
