  "Aurelion": "Aurelion",
  "Aus": "Off",
  "Aus dem Giftzahn einer Katakombenspinne geschliffen.": "Ground from the venom fang of a catacomb spider.",
  "Aus dem glühenden Innern des Kolosses gewoben.": "Woven from the glowing innards of the Colossus.",
  "Aus dem Holz des letzten Scheiterhaufens der Glutöde geschnitzt. Es brennt noch.": "Carved from the wood of the last pyre of the Ember Wastes. It still burns.",
  "Aus dem Kiefer einer Hyäne, die bis zuletzt gelacht hat.": "From the jaw of a hyena that laughed to the very end.",
  "Aus dem Panzer eines Eistrolls geschnitten. Er wird nie warm.": "Cut from the hide of an Ice Troll. It is never warm.",
  "Aus dem schwarzen Glas geschlagen, das der Vulkan unter Emberwrath ausspuckt.": "Struck from the black glass the volcano beneath Emberwrath spits out.",
  "Aus dem See steigen Ertrunkene. Die alten Totems am Ufer hielten sie einst zurück. Entzünde alle drei, dann können wir den Tempel betreten.": "The drowned are rising from the lake. The old totems on the shore once held them back. Light all three, and we can enter the temple.",
  "Aus den Fellen der Aschewölfe genäht.": "Stitched from the pelts of Ash Wolves.",
  "Aus den Glutprüfungen": "From the Ember Trials",
  "Aus den Schmiedehallen unter dem Aschegrat. Zwerge sind langsamer, tragen Rüstung aber wie eine zweite Haut und stecken Treffer weg, die andere fällen.": "From the forge halls beneath the Ash Ridge. Dwarves are slower, but wear armor like a second skin and shrug off blows that would fell others.",
  "Aus den Schuppen der Drachenmutter. Sie glühen noch.": "From the scales of the Mother of Drakes. They still glow.",
  "Aus den Zähnen der Aschewölfe gefädelt.": "Strung from the teeth of Ash Wolves.",
  "Aus der Krone des Tyrannen könnte ich Schmuck für ein Königreich machen. Aber die behältst du besser.": "I could make jewelry for a whole kingdom out of the tyrant's crown. But you'd better keep it.",
  "Aus einem Stück Gletschereis geschlagen, das in tausend Jahren nicht getaut ist.": "Hewn from a block of glacier ice that has not thawed in a thousand years.",
  "Aus einer Rippe Skalvyrs gebogen. Die Sehne knistert vor Kälte.": "Bent from one of Skalvyr's ribs. The string crackles with cold.",
  "Aus Glut geschmiedet": "Forged in Embers",
  "Aus Kristallseide macht man Bogensehnen, die bei jeder Kälte halten. Die Spinnen in den Reifhöhlen spinnen sie. Bring mir vier Bündel, und ich spanne dir einen Bogen, wie ihn noch kein Jarl hatte.": "Crystal Silk makes bowstrings that hold in any cold. The spiders in the Rime Caverns spin it. Bring me four bundles, and I'll string you a bow like no jarl has ever had.",
  "Ausdauer": "Stamina",
  "Ausgegeben an jeden, der eine Waffe halten kann.": "Issued to anyone who can hold a weapon.",
  "Ausrüsten": "Equip",
  "Ausrüstung": "Gear",
  "Ausrüstung, Proviant, Sold. Frag nicht, woher.": "Gear, provisions, pay. Don't ask where from.",
  "Ausrüstung, Proviant, Sold. Frag nicht, woher. Und wenn du Gold übrig hast: Verstärken kostet, lohnt sich aber.": "Gear, provisions, pay. Don't ask where from. And if you've got gold to spare: upgrading costs, but it pays off.",
