  "Banditen plündern die Flüchtlinge aus der Senke. Ihr Lager liegt im Osten des Waldes – folge dem Rauch. Zehn weniger, und sie überlegen es sich zweimal.": "Bandits are plundering the refugees from the hollow. Their camp lies in the east of the forest – follow the smoke. Ten fewer, and they'll think twice.",
