  "Bestellungen bewahren wir so lange auf, wie es die steuer- und handelsrechtlichen Aufbewahrungsfristen verlangen, in der Regel bis zu zehn Jahre (Art. 6 Abs. 1 lit. c DSGVO in Verbindung mit § 147 AO). Abgebrochene und nicht bezahlte Bestellungen löschen wir nach 90 Tagen. Wird eine Zahlung zurückgebucht, sperren wir weitere Käufe für das Konto, bis der Fall geklärt ist. Damit die Sperre nicht durch ein neues Konto umgangen wird, speichern wir dazu einen Prüfwert (Hash) deiner E&#8209;Mail-Adresse, aus dem sich die Adresse nicht zurückrechnen lässt. Er bleibt auch nach dem Löschen des Kontos erhalten und wird drei Jahre nach der Sperre oder sobald der Fall geklärt ist gelöscht. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO (Schutz vor Zahlungsausfällen und Betrug).": "We retain orders for as long as required by the retention periods under tax and commercial law, generally up to ten years (Art. 6(1)(c) GDPR in conjunction with § 147 AO, German Fiscal Code). We delete canceled and unpaid orders after 90 days. If a payment is charged back, we block further purchases for the account until the case is resolved. So that the block cannot be circumvented with a new account, we store a check value (hash) of your email address from which the address cannot be reconstructed. It is retained even after the account is deleted and is deleted three years after the block or as soon as the case is resolved. The legal basis is Art. 6(1)(f) GDPR (protection against payment defaults and fraud).",
