  "Beweg dich leise. Der Schnee verrät jeden Schritt, und die Pirscher hören alles.": "Move quietly. The snow betrays every step, and the stalkers hear everything.",
  "Beweg dich leise. Der Schnee verrät jeden Schritt.": "Move quietly. The snow betrays every step.",
  "Bezahlt wird auf der Bezahlseite von Stripe (Stripe Payments Europe, Limited, 1 Grand Canal Street Lower, Grand Canal Dock, Dublin, D02 H210, Irland). Dafür geben wir Stripe deine E&#8209;Mail-Adresse, Angebot, Preis und Bestellnummer weiter. Deine Zahlungsdaten (zum Beispiel Kartennummer oder PayPal-Konto) gibst du direkt bei Stripe ein, wir sehen sie nicht. Stripe verarbeitet diese Daten und Angaben zu deinem Gerät auch in eigener Verantwortung, um die Zahlung auszuführen, Betrug zu verhindern und gesetzliche Pflichten zu erfüllen. Dabei können Daten an Stripe, Inc. in den USA gehen; Stripe ist unter dem EU-US Data Privacy Framework zertifiziert. Mehr dazu in der": "Payment takes place on the Stripe checkout page (Stripe Payments Europe, Limited, 1 Grand Canal Street Lower, Grand Canal Dock, Dublin, D02 H210, Ireland). For this, we pass your email address, the offer, price and order number to Stripe. You enter your payment details (for example card number or PayPal account) directly with Stripe; we do not see them. Stripe also processes this data and information about your device under its own responsibility in order to execute the payment, prevent fraud and comply with legal obligations. In doing so, data may be transferred to Stripe, Inc. in the USA; Stripe is certified under the EU-US Data Privacy Framework. More on this in the",
  "Bezahlt wird auf der Bezahlseite von Stripe (Stripe Payments Europe, Limited, 1 Grand Canal Street Lower, Grand Canal Dock, Dublin, D02 H210, Irland). Dafür geben wir Stripe deine E&#8209;Mail-Adresse, Angebot, Preis und Bestellnummer weiter. Deine Zahlungsdaten (zum Beispiel Kartennummer oder PayPal-Konto) gibst du direkt bei Stripe ein, wir sehen sie nicht. Stripe verarbeitet diese Daten und Angaben zu deinem Gerät auch in eigener Verantwortung, um die Zahlung auszuführen, Betrug zu verhindern und gesetzliche Pflichten zu erfüllen. Dabei können Daten an Stripe, Inc. in den USA gehen; Stripe ist unter dem EU-US Data Privacy Framework zertifiziert. Mehr dazu in der <a href=\"https://stripe.com/de/privacy\" rel=\"noopener\" target=\"_blank\">Datenschutzerklärung von Stripe</a>. Wählst du eine Zahlungsart wie PayPal oder Klarna, gelten zusätzlich deren Datenschutzhinweise.": "Payment takes place on the Stripe checkout page (Stripe Payments Europe, Limited, 1 Grand Canal Street Lower, Grand Canal Dock, Dublin, D02 H210, Ireland). For this, we pass your email address, the offer, price and order number to Stripe. You enter your payment details (for example card number or PayPal account) directly with Stripe; we do not see them. Stripe also processes this data and information about your device under its own responsibility in order to execute the payment, prevent fraud and comply with legal obligations. In doing so, data may be transferred to Stripe, Inc. in the USA; Stripe is certified under the EU-US Data Privacy Framework. More on this in the <a href=\"https://stripe.com/de/privacy\" rel=\"noopener\" target=\"_blank\">Stripe Privacy Policy</a>. If you choose a payment method such as PayPal or Klarna, their privacy notices also apply.",
  "Bezahlung sicher über Stripe.": "Secure payment via Stripe.",
