  "Bist du unter 18, kaufe nur mit der Erlaubnis deiner Eltern oder Erziehungsberechtigten. Hat ein Kind oder Jugendlicher ohne diese Erlaubnis gekauft, können sich die Eltern beim": "If you are under 18, only make purchases with the permission of your parents or legal guardians. If a child or teenager has made a purchase without this permission, the parents can contact",
  "Bist du unter 18, kaufe nur mit der Erlaubnis deiner Eltern oder Erziehungsberechtigten. Hat ein Kind oder Jugendlicher ohne diese Erlaubnis gekauft, können sich die Eltern beim <a href=\"support\">Support</a> melden. Wir prüfen den Fall und erstatten den Betrag, wenn der Kauf nicht wirksam war. Gekauftes Gold und Designs ziehen wir dann wieder ab.": "If you are under 18, only make purchases with the permission of your parents or legal guardians. If a child or teenager has made a purchase without this permission, the parents can contact <a href=\"support\">Support</a>. We will review the case and refund the amount if the purchase was not valid. We will then deduct the purchased Gold and cosmetics again.",
