  "Brauchst du Stahl? Oder Tränke? Ich hab beides.": "Need steel? Or potions? I've got both.",
  "Brauchst du Stahl? Oder Tränke? Ich hab beides. Und einen Rat: Tief in der Senke streift ein grauer Wolf, älter als ich. Graumaul. Lass ihn in Ruhe, wenn du klug bist.": "Need steel? Or potions? I've got both. And some advice: deep in the hollow roams a gray wolf, older than me. Greymaw. Leave him be if you're smart.",
