  "Brot, Verbände, Pfeilspitzen. Nichts davon ist mehr warm, aber alles ist da. Die Bastion hält eine Woche länger. Das ist hier eine Ewigkeit.": "Bread, bandages, arrowheads. None of it is warm anymore, but it's all here. The Bastion holds another week. Out here, that's an eternity.",
