  "Eistrolle erschlagen": "Ice Trolls slain",
  "Elite": "Elite",
  "Elite-Gegner (orange auf der Karte) lassen bessere Beute fallen.": "Elite enemies (orange on the map) drop better loot.",
  "Elitejäger": "Elite Hunter",
  "Eliten tragen einen goldenen Namen.": "Elites bear a golden name.",
  "Elowen": "Elowen",
  "Elsa": "Elsa",
  "Emberon": "Emberon",
  "Emberwrath": "Emberwrath",
  "EMBERWRATH": "EMBERWRATH",
  "Emberwrath schläft ruhig. Aber in der Esse glüht es noch. Wer mutig ist, stellt sich dort den Glutprüfungen.": "Emberwrath sleeps soundly. But the Crucible still glows. Those with courage face the Ember Trials there.",
  "Emberwrath spielen – Pixel-Action-RPG im Browser": "Play Emberwrath – Pixel Action RPG in Your Browser",
  "Emberwrath Spielszene": "Emberwrath game scene",
  "Emberwrath Support": "Emberwrath Support",
  "Emberwrath wird ständig weiterentwickelt. Wir dürfen gekaufte Inhalte ändern, wenn es dafür einen triftigen Grund gibt, etwa die Ausgewogenheit des Spiels, technische Anpassungen oder neue Inhalte, und dir dadurch keine zusätzlichen Kosten entstehen. Preise von Gegenständen im Spiel können sich dabei ändern. Beeinträchtigt eine Änderung einen gekauften Inhalt mehr als nur unerheblich, informieren wir dich vorher per E&#8209;Mail oder im Spiel. Du kannst den Vertrag dann innerhalb von 30 Tagen nach der Änderung unentgeltlich beenden und bekommst den Kaufpreis anteilig zurück (§ 327r BGB).": "Emberwrath is constantly being developed further. We may change purchased content if there is a valid reason, such as game balance, technical adjustments or new content, and this does not cause you any additional costs. Prices of items in the game may change in the process. If a change impairs purchased content more than insignificantly, we will inform you in advance by email or in the game. You can then terminate the contract free of charge within 30 days of the change and receive a pro-rata refund of the purchase price (§ 327r BGB).",
  "Emberwrath, Klinge der Könige": "Emberwrath, Blade of Kings",
  "Empfohlen": "Recommended",
  "Empfohlen ab Stufe {0}": "Recommended from Level {0}",
  "Empfohlene Stufe {0}": "Recommended Level {0}",
