  "Essenstulpen": "Forge Gauntlets",
  "Essenzauberstab": "Forge Wand",
  "Etwas anderes (bitte beschreiben)": "Something else (please describe)",
  "Etwas Großes lebt in den tiefen Tümpeln. Die Leute nennen es das Moorgrauen. Es hat mehr meiner Wächter gefressen als alle Lauerer zusammen. Töte es und bring mir sein Herz. Ich will zusehen, wie es brennt.": "Something big lives in the deep pools. Folk call it the Bog Horror. It's eaten more of my wardens than all the Lurkers put together. Kill it and bring me its heart. I want to watch it burn.",
  "Etwas Seltenes streift hier umher: {0}": "Something rare roams here: {0}",
