  "Federn haben wir jetzt, aber keine Spitzen. Die Bogenschützen der Plünderer haben unsere Schmiede ausgeräumt. Nimm ihnen acht Spitzen ab. Sie schulden sie uns.": "We have fletching now, but no heads. The Raider archers cleaned out our forge. Take eight arrowheads off them. They owe us.",
