  "Feuerball": "Fireball",
  "Feuerball Rang 2: zwei kleinere Begleitflammen fliegen mit, die Explosion ist größer. +15 % Schaden.": "Fireball Rank 2: two smaller companion flames fly alongside, and the explosion is larger. +15% damage.",
  "Feuerball, Meteor und Flammenring: +12 % Schaden je Rang.": "Fireball, Meteor and Flame Nova: +12% damage per rank.",
  "Feuerkobolde vernichtet": "Fire Imps destroyed",
  "Feuerkobolde. Klein, flink, und sie zünden alles an, was nicht aus Stein ist. Zwölf davon, und meine Leute können wieder schlafen.": "Fire Imps. Small, quick, and they set fire to anything that isn't stone. Twelve of them, and my people can sleep again.",
