  "Figur eines Mitspielers nicht darstellbar": "Could not display another player's character",
  "Finde Brisas verschollene Karawane und vertreibe die Lauerer, die sie belagern.": "Find Brisa's lost caravan and drive off the Lurkers besieging it.",
  "Finde das Banditenlager und zerschlage die Bande.": "Find the bandit camp and break the gang.",
  "Finde das Tor zur Glutschmiede auf dem Gipfel.": "Find the gate to the Molten Forge on the summit.",
  "Finde dein erstes episches Item.": "Find your first Epic item.",
  "Finde den Kessel der Moorhexe und entscheide, was aus ihrem Rezept wird.": "Find the Bog Witch's cauldron and decide the fate of her recipe.",
  "Finde ein legendäres Item.": "Find a Legendary item.",
  "Finde eine Gruppe aus drei Helden für einen Dungeon.": "Find a party of three heroes for a dungeon.",
  "Finde eine Gruppe aus drei Helden. Sucht gerade niemand Passendes, füllen Söldner die freien Plätze.": "Find a party of three heroes. If no suitable players are searching, Mercenaries fill the open slots.",
  "Finde heraus, wer die Banditen bezahlt.": "Find out who is paying the bandits.",
  "Finde Oonas Kräutertasche, die sie auf der Flucht verloren hat.": "Find Oona's herb satchel, which she lost while fleeing.",
