  "Flammenkrone": "Flame Crown",
  "Flammenring": "Flame Nova",
  "Fleisch für den ganzen Winter. Heute Abend wird in der Halle gesungen, und dein Name kommt in der dritten Strophe vor. Die erste und zweite gehören den Toten.": "Meat for the whole winter. Tonight there will be singing in the hall, and your name comes up in the third verse. The first and second belong to the dead.",
  "Flieh in den goldenen Kreis!": "Flee into the golden circle!",
  "Flink und treffsicher": "Swift and true",
