  "Folge dem Pfad nach Osten in den Aschenwald.": "Follow the path east into the Ashwood.",
  "Folge den glühenden Pfotenabdrücken.": "Follow the glowing paw prints.",
  "Folge der Straße im Nordosten des Aschenwalds bergauf zu den Schlackenhöhen.": "Follow the road in the northeast of the Ashwood up the mountain to the Cinder Peaks.",
  "Folge der Straße nach Osten bis zum Marschrand und weiter zur Mirefeste.": "Follow the road east to Marsh's Edge and on to Mirekeep.",
  "Folgen des Widerrufs": "Effects of Withdrawal",
