  "Fragen zu einem Kauf beantwortet der Support.": "Questions about a purchase? Contact Support.",
  "Freigeschaltet ab Stufe {0}, nachdem Ignaroth gefallen ist.": "Unlocks at Level {0}, once Ignaroth has fallen.",
  "Frisch aus Marens Ofen. Stellt 25 Leben wieder her.": "Fresh from Maren's oven. Restores 25 Health.",
  "Frisch und eklig. Genau so, wie ich sie mag.": "Fresh and disgusting. Just the way I like them.",
  "Frische Ware aus drei Tälern! Na ja, zwei. Eins ist abgebrannt.": "Fresh wares from three valleys! Well, two. One burned down.",
  "Frische Zutaten": "Fresh Ingredients",
  "Frisur": "Hairstyle",
