  "Frostbeule": "Frostbite",
  "Frostbiss": "Frostbite",
  "Frostelch": "Frost Elk",
  "Frosthold": "Frosthold",
  "Frosthold erreicht": "Frosthold reached",
  "Frosthold isst heute. Danke, Jägerin. Oder Jäger. Im Schnee sehen wir alle gleich aus.": "Frosthold eats today. Thank you, huntress. Or hunter. In the snow we all look the same.",
  "Frosthold isst, was die Jäger bringen. Zwölf Wölfe oder Pirscher, dann isst Frosthold heute. Morgen fragen wir wieder.": "Frosthold eats what the hunters bring. Twelve wolves or stalkers, and Frosthold eats today. Tomorrow we ask again.",
  "Frosthold steht, solange einer von uns noch eine Axt heben kann.": "Frosthold stands as long as one of us can still raise an axe.",
  "Frosthold steht, solange einer von uns noch eine Axt heben kann. Also für immer.": "Frosthold stands as long as one of us can still raise an axe. So, forever.",
  "Frostnova – hinter Eis Deckung suchen oder durch den Ring rollen": "Frost Nova – take cover behind ice or roll through the ring",
  "Frostpass": "Frost Pass",
  "Frostspitze": "Frostspire",
  "Frostwiedergänger": "Frost Revenant",
  "Frostwolf": "Frost Wolf",
  "Frostwölfe erlegt": "Frost Wolves slain",
  "Frostwölfe und Schneepirscher an den Hängen.": "Frost Wolves and Snow Stalkers on the slopes.",
  "Frostwolfsfell": "Frost Wolf Pelt",
  "Frostwolfsfelle gesammelt": "Frost Wolf pelts gathered",
  "Frostzeichen": "Frost Charm",
  "Frostzeichen erbeutet": "Frost Charms taken",
  "Früher brannten drei Leuchtfeuer auf den Zinnen. Solange sie brannten, wagte sich kein Troll ins Tal. Die Hexen haben sie gelöscht. Entzünde sie wieder, und die Trolle bleiben, wo sie hingehören.": "Three beacons once burned on the peaks. As long as they burned, no troll dared enter the valley. The witches put them out. Light them again, and the trolls will stay where they belong.",
  "Früher brannten drei Leuchtfeuer auf den Zinnen. Solange sie brannten, wagte sich kein Troll ins Tal. Die Hexen haben sie gelöscht. Nimm diese drei Krüge Brandöl, gieß sie in die Feuerschalen und entzünde sie wieder. Dann bleiben die Trolle, wo sie hingehören.": "Three beacons once burned on the peaks. As long as they burned, no troll dared enter the valley. The witches put them out. Take these three jugs of Fire Oil, pour them into the braziers and light them again. Then the trolls will stay where they belong.",
  "Früher hatte die Grenzwacht drei Posten im Wald: am Nordhang, am Bach im Osten und an der alten Eiche im Süden. Seit dem Ascheregen war keiner mehr dort. Geh hin und sieh nach, ob noch etwas steht. Und wer dort jetzt wohnt.": "The Borderwatch once kept three posts in the woods: on the north slope, by the stream in the east, and at the old oak in the south. No one's been there since the ashfall. Go and see if anything still stands. And who lives there now.",
  "Füllt einen freien Platz": "Fills an open slot",
  "Füllt Leben und Ressource vollständig auf.": "Fully restores Health and resource.",
  "Fünf Pfeile auf einmal – ideal gegen Gruppen.": "Five arrows at once – ideal against groups.",
  "Fünfzehn Feinde auf den Schlackenhöhen.": "Fifteen enemies on the Cinder Peaks.",
  "Fünfzehn Felle. Die Skalden werden davon singen. Kurz. Hier oben singen sie nur kurz, sonst frieren ihnen die Lippen fest.": "Fifteen pelts. The skalds will sing of this. Briefly. Up here they only sing briefly, or their lips freeze shut.",
  "Fünfzehn Trolle. Ich habe in meinem Leben drei erschlagen und darauf ein Fass geleert. Für dich rolle ich zwei heraus.": "Fifteen trolls. I've slain three in my whole life and drained a barrel for it. For you, I'll roll out two.",
  "Fünfzehn. Nicht schlecht für jemanden aus dem Süden. Vielleicht bleibst du doch länger als eine Woche am Leben.": "Fifteen. Not bad for a southerner. Maybe you'll live longer than a week after all.",
  "Funken tropfen von seiner Spitze wie Wasser.": "Sparks drip from its tip like water.",
  "Funkenflug": "Sparkdrift",
  "Funkenplage": "A Plague of Sparks",
  "für das Team reserviert": "reserved for the team",
  "Für den Versand des Newsletters, der Bestellbestätigungen und einiger Konto-E&#8209;Mails nutzen wir Resend (Resend, Inc., San Francisco, USA) als Auftragsverarbeiter. Resend erhält dafür deine E&#8209;Mail-Adresse und den Inhalt der E&#8209;Mail. Die Übermittlung in die USA erfolgt auf Grundlage der EU-Standardvertragsklauseln. Die Abonnentenliste selbst liegt in unserer Datenbank bei Supabase.": "We use Resend (Resend, Inc., San Francisco, USA) as a processor for sending the newsletter, order confirmations and some account emails. For this purpose, Resend receives your email address and the content of the email. The transfer to the USA is based on the EU Standard Contractual Clauses. The subscriber list itself is stored in our database at Supabase.",
  "Für die Haftung gilt Abschnitt 9 der": "Liability is governed by Section 9 of the",
  "Für die Haftung gilt Abschnitt 9 der <a href=\"nutzungsbedingungen#haftung\">Nutzungsbedingungen</a>. Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen. Es gilt deutsches Recht. Wenn du Verbraucher in einem anderen EU-Land bist, bleiben dir die zwingenden Schutzvorschriften deines Landes erhalten.": "Section 9 of the <a href=\"nutzungsbedingungen#haftung\">Terms of Use</a> applies to liability. We are neither willing nor obliged to participate in dispute resolution proceedings before a consumer arbitration board. German law applies. If you are a consumer in another EU country, you retain the protection of the mandatory consumer protection provisions of your country.",
  "Für Holz gemacht. Wölfe sind auch aus Holz, wenn man fest genug zuschlägt.": "Made for wood. Wolves are wood too, if you swing hard enough.",
