  "Gold kaufen geht nur mit einem Charakter in deinem Konto.": "You need a character in your account to buy Gold.",
  "Gold und Designs kannst du auch im Shop gegen echtes Geld kaufen. Dafür gelten zusätzlich die": "You can also buy Gold and cosmetics in the Shop for real money. This is additionally governed by the",
  "Gold und Designs kannst du auch im Shop gegen echtes Geld kaufen. Dafür gelten zusätzlich die <a href=\"kaufbedingungen\">Kaufbedingungen</a>. Sie gehen diesen Bedingungen vor, wenn sich beide widersprechen.": "You can also buy Gold and cosmetics in the Shop for real money. The <a href=\"kaufbedingungen\">Purchase Terms</a> also apply to this. They take precedence over these terms if the two conflict.",
  "Gold und Designs kommen beim nächsten Spielstart automatisch an. Fehlt etwas, schreib uns über das Formular oben und nenne die E&#8209;Mail-Adresse deines Kontos und das Datum des Kaufs. Hat dein Kind ohne deine Erlaubnis gekauft, melde dich ebenfalls hier. Alles Weitere steht in den": "Gold and cosmetics arrive automatically the next time you start the game. If something is missing, write to us using the form above and include your account’s email address and the date of purchase. If your child made a purchase without your permission, please contact us here as well. Everything else is set out in the",
  "Gold und Designs kommen beim nächsten Spielstart automatisch an. Fehlt etwas, schreib uns über das Formular oben und nenne die E&#8209;Mail-Adresse deines Kontos und das Datum des Kaufs. Hat dein Kind ohne deine Erlaubnis gekauft, melde dich ebenfalls hier. Alles Weitere steht in den <a href=\"kaufbedingungen\">Kaufbedingungen</a>.": "Gold and cosmetics arrive automatically the next time you start the game. If something is missing, write to us using the form above and include your account’s email address and the date of purchase. If your child made a purchase without your permission, please contact us here as well. Everything else is set out in the <a href=\"kaufbedingungen\">Purchase Terms</a>.",
  "Gold und Designs werden sofort nach der Bestätigung der Zahlung in deinem Konto bereitgestellt und sind beim nächsten Spielstart da, meist schon nach wenigen Sekunden. Kommt etwas nicht an, schreib uns über den": "Gold and cosmetics are provided in your account immediately after the payment is confirmed and are available the next time you start the game, usually within a few seconds. If something doesn’t arrive, contact us via",
  "Gold und Designs werden sofort nach der Bestätigung der Zahlung in deinem Konto bereitgestellt und sind beim nächsten Spielstart da, meist schon nach wenigen Sekunden. Kommt etwas nicht an, schreib uns über den <a href=\"support\">Support</a>.": "Gold and cosmetics are provided in your account immediately after the payment is confirmed and are available the next time you start the game, usually within a few seconds. If something doesn’t arrive, contact us via <a href=\"support\">Support</a>.",
