  "Gorm Eisfaust besiegt": "Gorm Icefist defeated",
  "Gorm Eisfaust führt die Trolle. Er ist größer als drei Männer und schlauer als die meisten Jarle. Er trägt die Flammenkrone auf der Brust, eingebrannt ins Fell. Bring mir seinen Hauer, damit mein Volk sieht, dass er tot ist.": "Gorm Icefist leads the trolls. He's bigger than three men and cleverer than most jarls. He bears the Flame Crown on his chest, burned into his hide. Bring me his tusk, so my people can see he's dead.",
  "Gorm hält sich in der tiefsten Trollhöhle auf.": "Gorm lairs in the deepest of the Troll Caves.",
