  "Gut gespielt": "Well played",
  "Gut gespielt!": "Well played!",
  "Gute Arbeit. Das Lager qualmt nur noch halb so viel.": "Good work. The camp is only smoking half as much.",
  "Gute Arbeit. Frosthold schläft ruhiger, und ich zähle Münzen. Alle gewinnen.": "Good work. Frosthold sleeps easier, and I count coins. Everyone wins.",
  "Gute Federn, grau vom Wind. Meine Söhne werden heute Nacht Pfeile schnitzen.": "Good feathers, gray from the wind. My sons will carve arrows tonight.",
  "Gute Felle. Und jetzt hoch mit dir … Fersen runter, Rücken gerade. Siehst du, du kannst reiten. Ein Tier bekommst du von mir aber nicht geschenkt. Meine Pferde kosten, und wilde Tiere musst du dir selbst verdienen.": "Good hides. Now up you go… Heels down, back straight. See, you can ride. But I won't give you an animal for free. My horses cost money, and wild beasts you'll have to earn yourself.",
  "Gute Jagd. Der Wind ist auf deiner Seite.": "Good hunting. The wind is on your side.",
  "gz!": "gz!",
  "H / 3": "H / 3",
  "Haarfarbe": "Hair Color",
  "Hab die Fläche nicht gesehen": "Didn't see the AoE",
  "halb": "half",
  "Halb unten!": "Half down!",
  "Hale": "Hale",
  "Hale hat dich losgeschickt, also soll er es von dir hören, nicht von einem Boten. Nimm den langen Weg zurück: durch die Zinnen, die Marsch, die Steppe. Sieh dir an, was du verändert hast. Dann sag ihm, dass es vorbei ist.": "Hale sent you out, so he should hear it from you, not from some messenger. Take the long way back: through the peaks, the marsh, the steppe. See what you've changed. Then tell him it's over.",
  "Hale schickt dich? Dann hat er endlich auf meine Briefe gehört. Willkommen am Außenposten. Viel ist nicht übrig, aber es steht noch.": "Hale sent you? Then he finally listened to my letters. Welcome to the outpost. There's not much left, but it's still standing.",
  "Hale wartet oben in Rauhwacht. Grüß ihn von mir und sag ihm, dass er mir noch ein Fass schuldet.": "Hale is waiting up in Rookwatch. Give him my regards and tell him he still owes me a barrel.",
  "Hale will die Glutschmiede stürmen, und ich soll dafür Rammen bauen, die nicht sofort verbrennen. Glutkerne, vier Stück. Die Schmiedegolems und Drachen dort drin tragen sie im Leib.": "Hale wants to storm the Molten Forge, and I'm supposed to build rams that don't burn up on the spot. Ember Cores, four of them. The Forge Golems and drakes in there carry them inside their bodies.",
  "Hallo": "Hello",
  "Hallo zusammen": "Hi all",
  "Hallo!": "Hello!",
  "Halsabschneider": "Cutthroat",
  "Halsband: Aschenwolf": "Collar: Ash Wolf",
  "Halsberge der Aschewacht": "Ashguard Hauberk",
  "Hält die Gegner auf sich und schützt die Gruppe.": "Draws the enemies' attention and protects the party.",
  "Halt die Klinge bereit. In der Steppe kommt der Tod auf vier Beinen, und meistens auf mehr als einem Pferd.": "Keep your blade ready. On the Steppe, death comes on four legs, and usually on more than one horse.",
  "Halt die Klinge bereit. In der Steppe kommt der Tod auf vier Beinen.": "Keep your blade ready. On the Steppe, death comes on four legs.",
  "Halt durch, wir machen das": "Hang in there, we got this",
  "Hält Gegner mit präzisen Pfeilen auf Abstand. Fokus lädt sich schnell auf und speist Salven und durchschlagende Schüsse.": "Keeps enemies at bay with precise arrows. Focus recharges quickly and fuels volleys and piercing shots.",
  "Halte die Augen offen. Der Wald hat mehr Zähne als Bäume.": "Keep your eyes open. This forest has more teeth than trees.",
  "Halte die Augen offen. Der Wald hat mehr Zähne als Bäume. Und eine Axt: Borka, die Aschenhauerin, zieht am Waldweg entlang. Drei meiner Hauptmänner hat sie schon.": "Keep your eyes open. This forest has more teeth than trees. And one axe: Borka, the Ash Hewer, roams along the forest road. She's already taken three of my captains.",
  "Halte die Jagdhütte mit Sigrun, bis der Sturm vorüber ist.": "Hold the hunting lodge with Sigrun until the storm has passed.",
  "Halte die Pilgerstraße frei von Geistern und Schlangen.": "Keep the Pilgrim Road clear of wraiths and serpents.",
  "Halte die Stege zum Sporenschlund frei, damit Thanes Späher durchkommen.": "Keep the boardwalks to the Spore Hollow clear so Thane's scouts can get through.",
  "Halte Sigruns Jagdhütte gegen die Frostwiedergänger, bis der Morgen kommt.": "Hold Sigrun's hunting lodge against the Frost Revenants until dawn.",
