  "Heimkehr": "Homecoming",
  "Heiß genug, um Wunden sofort zu versiegeln – das hilft dem Opfer nur nicht.": "Hot enough to sear wounds shut instantly – which does the victim no good.",
  "Heiß! Heiß! Aber gut. Mit diesen Schuppen gehe ich durch jedes Feuer.": "Hot! Hot! But good. With these scales I can walk through any fire.",
