  "Heute Nacht schläft der Außenposten zum ersten Mal seit Wochen. Hier, nimm das. Du brauchst es dringender als unsere Toten.": "Tonight the outpost sleeps for the first time in weeks. Here, take this. You need it more than our dead do.",
