  "Isgard": "Isgard",
  "ist die Spielwährung von Emberwrath. Gekauftes Gold wird dem Charakter gutgeschrieben, den du beim Kauf auswählst. Es lässt sich nicht auf andere Charaktere oder Konten übertragen.": "is the in-game currency of Emberwrath. Purchased Gold is credited to the character you select at purchase. It cannot be transferred to other characters or accounts.",
