  "Jarlszweihänder": "Jarl's Greatsword",
  "Jede davon hat eine Geschichte. Ich werde sie alle erzählen, wenn ich am Thron bin.": "Each one has a story. I'll tell them all when I reach the Throne.",
  "Jede Karawane, die hier durchkommt, bringt mir Geld. Jeder Plünderer, der sie überfällt, kostet mich Geld. Zwanzig Feinde weniger, und ich teile den Gewinn mit dir. Jedes Mal.": "Every caravan that comes through here makes me money. Every raider who robs one costs me money. Twenty fewer foes, and I'll share the profit with you. Every time.",
  "Jede Nacht kommen sie näher. Frostwiedergänger, die Toten der letzten Winter. Heute Nacht greifen sie die Hütte an, ich spüre es in den Zähnen. Bleib bei mir. Wenn die Hütte bis zum Morgen steht, haben wir gewonnen.": "Every night they come closer. Frost Revenants, the dead of winters past. Tonight they'll attack the lodge, I can feel it in my teeth. Stay with me. If the lodge still stands at dawn, we've won.",
  "Jede Schuppe stammt von einem anderen Tier, das der Sumpf verschlungen hat.": "Every scale comes from a different beast the swamp has swallowed.",
  "Jede Welt fasst bis zu {0} Spieler je Gebiet. Ist eine voll, öffnet sich automatisch die nächste.": "Each world holds up to {0} players per zone. When one is full, the next opens automatically.",
  "Jeder Dornkriecher im Aschenwald ist aus ihrem Leib gekrochen.": "Every Thorn Crawler in the Ashwood crawled out of her body.",
  "Jeder Hieb lässt einen Funkenregen zurück.": "Every swing leaves a shower of sparks.",
  "Jeder Hieb lässt einen grauen Schleier zurück, der langsam zu Boden sinkt.": "Every strike leaves a gray veil that slowly sinks to the ground.",
  "Jeder Pfeil zählt. Jeder Trank auch. Unterschreib.": "Every arrow counts. Every potion, too. Sign.",
  "Jeder Pfeil zieht einen Schweif aus Licht hinter sich her.": "Every arrow draws a tail of light behind it.",
  "Jeder Schritt hinterlässt eine glimmende Spur.": "Every step leaves a smoldering trail.",
  "Jeder Schritt lässt den Boden glimmen.": "Every step makes the ground smolder.",
  "Jeder Schritt zum Thron ist ein Gebet.": "Every step toward the Throne is a prayer.",
  "Jeder Schritt zum Thron ist ein Gebet. Leider sind viele meiner Schritte gerade eher Flüche.": "Every step toward the Throne is a prayer. Sadly, a lot of my steps lately have been more like curses.",
  "Jep": "Yep",
  "Jetzt bestätigen": "Confirm Now",
  "Jetzt speichern": "Save Now",
  "Jorun": "Jorun",
  "K / Shift / Rechtsklick": "K / Shift / Right-click",
  "Kael": "Kael",
  "Kaelthar": "Kaelthar",
  "Kahlschlag": "Clear-Cut",
  "Kalrok": "Kalrok",
  "Kalt wie ein Grab und fast ebenso unzerbrechlich.": "Cold as a grave and nearly as unbreakable.",
  "Kalt, egal wie lange man sie trägt.": "Cold, no matter how long you wear them.",
  "Kaltes Wasser in der Glutöde. Wenn du mich fragst, ist das das größere Wunder als der tote Koloss.": "Cold water in the Ember Wastes. If you ask me, that's a bigger miracle than the dead Colossus.",
  "Kaltschnauze": "Coldsnout",
  "Kamm": "Mohawk",
  "Kampf": "Combat",
  "Kampf, Zauber, Umgebung": "Combat, spells, ambience",
  "kannst du freiwillig Gold und Designs kaufen. Alles, was du zum Spielen brauchst, erspielst du auch ohne Kauf.": ", you can optionally buy Gold and cosmetics. Everything you need to play can also be earned without buying anything.",
