  "Kauf&shy;bedingungen": "Purchase Terms",
  "Kaufbedingungen": "Purchase Terms",
  "Kaufbedingungen – Emberwrath": "Purchase Terms – Emberwrath",
  "Kaufbedingungen für Gold und Designs im Shop von Emberwrath, mit Widerrufsbelehrung und Muster-Widerrufsformular.": "Purchase Terms for Gold and cosmetics in the Emberwrath Shop, with Cancellation Policy and Model Withdrawal Form.",
  "Kaufe ein Reittier bei Stallmeisterin Orla oder erbeute eines von Bossen.": "Buy a mount from Stablemaster Orla or win one from bosses.",
  "Käufe im Shop": "Purchases in the Shop",
  "Käufe sind für dein Konto gesperrt. Bitte wende dich an den Support.": "Purchases are blocked for your account. Please contact Support.",
  "Kaufen": "Buy",
  "Kaufen · {0}": "Buy · {0}",
  "Kaufen geht nur mit einem Charakter in deinem Konto.": "Purchases only work with a character on your account.",
  "Kaufst du im Shop Gold oder ein Design, speichern wir zu deiner Bestellung: Bestellnummer, Konto- und bei Gold die Charakterkennung, Angebot, Preis, Zeitpunkt deiner Zustimmung zur sofortigen Ausführung (Widerrufsrecht), Status und Zeitpunkte von Zahlung, Gutschrift und gegebenenfalls Erstattung sowie die Kennungen der Zahlung bei Stripe. Damit wickeln wir den Kauf ab und schreiben ihn gut (Art. 6 Abs. 1 lit. b DSGVO). Die Bestellbestätigung schicken wir dir über Resend (siehe": "If you buy Gold or a cosmetic in the Shop, we store the following for your order: order number, account identifier and, for Gold, character identifier, offer, price, the time of your consent to immediate performance (right of withdrawal), status and times of payment, crediting and, where applicable, refund, as well as the payment identifiers at Stripe. We use this to process and credit the purchase (Art. 6(1)(b) GDPR). We send you the order confirmation via Resend (see",
  "Kaufst du im Shop Gold oder ein Design, speichern wir zu deiner Bestellung: Bestellnummer, Konto- und bei Gold die Charakterkennung, Angebot, Preis, Zeitpunkt deiner Zustimmung zur sofortigen Ausführung (Widerrufsrecht), Status und Zeitpunkte von Zahlung, Gutschrift und gegebenenfalls Erstattung sowie die Kennungen der Zahlung bei Stripe. Damit wickeln wir den Kauf ab und schreiben ihn gut (Art. 6 Abs. 1 lit. b DSGVO). Die Bestellbestätigung schicken wir dir über Resend (siehe <a href=\"#newsletter\">Newsletter</a>) an die E&#8209;Mail-Adresse deines Kontos.": "If you buy Gold or a cosmetic in the Shop, we store the following for your order: order number, account identifier and, for Gold, character identifier, offer, price, the time of your consent to immediate performance (right of withdrawal), status and times of payment, crediting and, where applicable, refund, as well as the payment identifiers at Stripe. We use this to process and credit the purchase (Art. 6(1)(b) GDPR). We send you the order confirmation via Resend (see <a href=\"#newsletter\">Newsletter</a>) to the email address of your account.",
  "Kazrak": "Kazrak",
  "Kazrin": "Kazrin",
  "Keiler, Banditen, Kriecher – ist mir egal. Zwölf davon weniger, und die Handelsstraße bleibt offen. Das ist mir was wert.": "Boars, bandits, crawlers – I don't care. Twelve fewer, and the trade road stays open. That's worth something to me.",
  "Keilersuhle": "Boar Wallow",
  "Keilerwiese": "Boar Meadow",
  "Kein Account eingeloggt": "No account signed in",
  "kein ding": "no prob",
  "Kein Ding, wir schaffen das": "No worries, we can do this",
  "kein Dungeon für deine Stufe": "no dungeon for your level",
  "Kein Dungeon passt gerade zu deiner Stufe.": "No dungeon matches your level right now.",
  "Kein Feuerregen mehr. Meine Leute stehen auf den Mauern und schauen einfach nur in den Himmel.": "No more fire raining down. My people stand on the walls and just stare at the sky.",
  "Kein Kreischen mehr über der Straße. Die Fuhrleute werden dir ein Lied schreiben. Ein schlechtes, aber immerhin.": "No more shrieking above the road. The carters will write you a song. A bad one, but still.",
