  "Kesh teilt sein Jagdrecht mit dir: Hyänen und Geier.": "Kesh shares his hunting rights with you: hyenas and vultures.",
  "Kesh, der Nomade": "Kesh the Nomad",
  "Ketta": "Ketta",
  "Kette": "Mail",
  "Kettenhandschuhe": "Chain Gloves",
  "Kettenhemd": "Chain Shirt",
  "Kettenhemd des Steppenfürsten": "Steppe Lord's Hauberk",
  "Kettenschienen": "Chain Greaves",
  "Kevlarkeks": "KevlarCookie",
  "Khar besiegt": "Khar defeated",
  "Khar hält sich in der Mitte seines Lagers auf. Er ist kein gewöhnlicher Krieger.": "Khar keeps to the center of his camp. He is no ordinary warrior.",
  "Khar hat drei Kriegsbanner in der Steppe aufgestellt. Wo sie wehen, strömen die Stämme zu ihm. Nimm diese Pechfackeln und brenn sie nieder, eins nach dem anderen. Ohne Banner ist er nur ein Mann mit einem großen Pferd.": "Khar has raised three War Banners across the steppe. Wherever they fly, the tribes flock to him. Take these pitch torches and burn them down, one by one. Without his banners, he's just a man with a big horse.",
  "Khar hat drei Kriegsbanner in der Steppe aufgestellt. Wo sie wehen, strömen die Stämme zu ihm. Reiß sie nieder, eins nach dem anderen. Ohne Banner ist er nur ein Mann mit einem großen Pferd.": "Khar has raised three War Banners across the steppe. Wherever they fly, the tribes flock to him. Tear them down, one by one. Without his banners, he's just a man with a big horse.",
  "Khar ist tot, aber seine Reiter sind es nicht. Sie sammeln sich in kleinen Gruppen und suchen einen neuen Anführer. Lass sie keinen finden. Fünfzehn weniger, und die Stämme wissen, wohin der Wind weht.": "Khar is dead, but his riders aren't. They're gathering in small bands, looking for a new leader. Don't let them find one. Fifteen fewer, and the tribes will know which way the wind blows.",
  "Khar reitet nie ohne sein Kriegshorn. Mit ihm ruft er die Stämme, und die Stämme gehorchen. Stell ihn, nimm ihm das Horn ab und bring es mir. Ich will es vor allen Augen zerbrechen.": "Khar never rides without his War Horn. With it he calls the tribes, and the tribes obey. Hunt him down, take the horn from him, and bring it to me. I want to break it for all to see.",
  "Khar weiß jetzt, dass es dich gibt. Er zieht seine Leute im Kriegslager zusammen. Bevor er zu uns kommt, gehen wir zu ihm. Schlag dich bis zum Lager durch und erschlag fünfzehn seiner Krieger.": "Khar knows you exist now. He's gathering his people in the War Camp. Before he comes to us, we go to him. Fight your way to the camp and slay fifteen of his warriors.",
  "Khar, der Steppenfürst": "Khar, the Steppe Lord",
  "Khar, der Steppenfürst (Aschensteppe)": "Khar, the Steppe Lord (Ashen Steppe)",
  "Khars Horn liegt zerbrochen vor meinem Zelt. Jeden Morgen trete ich einmal drauf. Nur um sicherzugehen.": "Khar's horn lies broken outside my tent. Every morning I step on it once. Just to be sure.",
  "Khars Kriegshorn": "Khar's War Horn",
  "Khars Kriegslager": "Khar's War Camp",
  "Khars Kriegslager erreicht": "Khar's War Camp reached",
  "Khars Rüstung. An den Ringen kleben noch Staub und Blut.": "Khar's armor. Dust and blood still cling to the rings.",
  "Kiste ({0}/{1})": "Chest ({0}/{1})",
  "Kisten im Schlamm": "Crates in the Mud",
