  "Konten ({0})": "Accounts ({0})",
  "Konten und Charaktere aller Spieler": "Accounts and characters of all players",
  "Konten und Charaktere liegen beim Dienst Supabase (Supabase Inc., USA) in einem Rechenzentrum in Frankfurt am Main. Supabase verarbeitet die Daten in unserem Auftrag (Art. 28 DSGVO). Soweit Supabase dabei aus den USA auf Daten zugreifen kann, gelten die EU-Standardvertragsklauseln aus dem Auftragsverarbeitungsvertrag. Deine gespeicherten Spielstände kann nur dein eigenes Konto lesen. Was andere Spieler im Spiel von dir sehen, steht im nächsten Abschnitt. Eine Übersicht mit Zahlen (Anzahl Konten und Charaktere, Stufen, Registrierungsdatum) sieht nur der Betreiber. Weitere Informationen:": "Accounts and characters are stored with the Supabase service (Supabase Inc., USA) in a data center in Frankfurt am Main, Germany. Supabase processes the data on our behalf as a processor (Art. 28 GDPR). Insofar as Supabase may access data from the USA, the EU Standard Contractual Clauses in the data processing agreement apply. Your saved game progress can only be read by your own account. What other players see of you in the game is described in the next section. An overview with figures (number of accounts and characters, levels, registration date) is visible only to the operator. More information:",
  "Konten und Charaktere liegen beim Dienst Supabase (Supabase Inc., USA) in einem Rechenzentrum in Frankfurt am Main. Supabase verarbeitet die Daten in unserem Auftrag (Art. 28 DSGVO). Soweit Supabase dabei aus den USA auf Daten zugreifen kann, gelten die EU-Standardvertragsklauseln aus dem Auftragsverarbeitungsvertrag. Deine gespeicherten Spielstände kann nur dein eigenes Konto lesen. Was andere Spieler im Spiel von dir sehen, steht im nächsten Abschnitt. Eine Übersicht mit Zahlen (Anzahl Konten und Charaktere, Stufen, Registrierungsdatum) sieht nur der Betreiber. Weitere Informationen: <a href=\"https://supabase.com/privacy\" rel=\"noopener\" target=\"_blank\">Datenschutzerklärung von Supabase</a>.": "Accounts and characters are stored with the Supabase service (Supabase Inc., USA) in a data center in Frankfurt am Main, Germany. Supabase processes the data on our behalf as a processor (Art. 28 GDPR). Insofar as Supabase may access data from the USA, the EU Standard Contractual Clauses in the data processing agreement apply. Your saved game progress can only be read by your own account. What other players see of you in the game is described in the next section. An overview with figures (number of accounts and characters, levels, registration date) is visible only to the operator. More information: <a href=\"https://supabase.com/privacy\" rel=\"noopener\" target=\"_blank\">Supabase Privacy Policy</a>.",
