  "Konto löschen": "Delete Account",
  "Konto und Charaktere speichern wir, solange dein Konto besteht. Du kannst es jederzeit selbst im Spiel löschen (nach der Anmeldung „Konto löschen“) oder über die <a href=\"support?anliegen=loeschen\">Support-Seite</a> löschen lassen. Dann löschen wir Konto, Charaktere und Spielstände. Ausgenommen sind Bestellungen aus dem Shop, die wir aus steuerlichen Gründen aufbewahren müssen (siehe <a href=\"#shop\">Käufe im Shop</a>); sie sind dann nicht mehr mit deinem Konto verbunden.": "We store your account and characters for as long as your account exists. You can delete it yourself at any time in the game (after signing in, “Delete Account”) or have it deleted via the <a href=\"support?anliegen=loeschen\">Support page</a>. Then we delete your account, characters and game progress. This does not apply to orders from the Shop, which we must retain for tax reasons (see <a href=\"#shop\">Purchases in the Shop</a>); they are then no longer linked to your account.",
