  "Kurz": "Short",
  "Kurz gesagt: Für dein Konto speichern wir deine E&#8209;Mail-Adresse, deinen Anzeigenamen und deine Charaktere, bei Käufen im Shop außerdem deine Bestellungen. Wir setzen keine Cookies und verwenden keine Werbe- oder Analysedienste.": "In short: for your account, we store your email address, your display name and your characters, and for purchases in the Shop also your orders. We do not set cookies and do not use any advertising or analytics services.",
