  "Letzte Bastion": "Last Bastion",
  "Letzte Bastion erreicht": "Reach the Last Bastion",
  "Letzte Woche haben die Plünderer eine ganze Ladung Gewürze geraubt. Gewürze! Was will ein Plünderer mit Safran? Sie tragen die Ballen noch mit sich herum, weil sie keiner kaufen will. Bring mir sechs zurück.": "Last week the Raiders stole a whole load of spices. Spices! What does a raider want with saffron? They're still hauling the bales around because nobody will buy them. Bring me six back.",
  "Letztes Licht": "Last Light",
  "Leuchtend, frisch, giftig. Perfekt. Wenn das klappt, singen sie in der Mirefeste Lieder über dich. Schlechte Lieder, aber immerhin.": "Glowing, fresh, poisonous. Perfect. If this works, they'll sing songs about you in Mirekeep. Bad songs, but still.",
  "Leuchtende Sporen tanzen um den Saum, aber sie schaden nur anderen.": "Glowing spores dance around the hem, but they only harm others.",
  "Leuchtfeuer": "Beacon",
  "Leuchtfeuer entzünden": "Light beacon",
  "Leuchtfeuer entzündet": "Beacons lit",
  "Leuchtfeuer mit Brandöl entzündet": "Beacons lit with Fire Oil",
