  "Level-Zeile {0} hat falsche Breite": "Level-Zeile {0} hat falsche Breite",
  "Lies selbst. Jede Lieferung trägt dasselbe Zeichen: das Siegel von Vesk, unserem Händler. Er hat beide Seiten beliefert. Was soll ich mit ihm machen? Du hast das Buch gefunden. Entscheide du.": "Read it yourself. Every shipment bears the same mark: the seal of Vesk, our own merchant. He's been supplying both sides. What should I do with him? You found the ledger. You decide.",
