  "Löschen": "Delete",
  "löschen lassen. Dann löschen wir Konto, Charaktere und Spielstände. Ausgenommen sind Bestellungen aus dem Shop, die wir aus steuerlichen Gründen aufbewahren müssen (siehe": ". Then we delete your account, characters and game progress. This does not apply to orders from the Shop, which we must retain for tax reasons (see",
  "Löschst du dein Konto oder einen Charakter selbst, verfallen die gekauften Inhalte darin ohne Erstattung. Sperren wir ein Konto wegen eines schweren oder wiederholten Verstoßes gegen die Nutzungsbedingungen, verfallen die gekauften Inhalte ebenfalls. Gesetzliche Ansprüche bleiben unberührt.": "If you delete your account or a character yourself, the purchased content in it is forfeited without refund. If we ban an account for a serious or repeated violation of the Terms of Use, the purchased content is likewise forfeited. Statutory claims remain unaffected.",
