  "Mist": "Damn",
  "Mit „Kaufen“ kommst du zur Bezahlseite unseres Zahlungsdienstleisters Stripe. Dort siehst du Angebot und Endpreis noch einmal und kannst Eingaben korrigieren oder den Kauf ohne Kosten abbrechen.": "Clicking “Buy” takes you to the checkout page of our payment service provider Stripe. There you will see the offer and the final price once more and can correct your entries or cancel the purchase at no cost.",
  "Mit „Weiter mit Google“ akzeptierst du die ": "By choosing “Continue with Google”, you accept the ",
  "Mit „Weiter mit Google“ akzeptierst du die Nutzungsbedingungen.": "By choosing “Continue with Google”, you accept the Terms of Use.",
  "Mit deinem Emberwrath-Konto spielen": "Play with your Emberwrath account",
  "Mit dem Klick auf „Bezahlen“ gibst du ein verbindliches Angebot ab. Der Vertrag kommt zustande, wenn die Zahlung bestätigt ist. Du bekommst dann eine Bestellbestätigung per E&#8209;Mail.": "By clicking “Pay”, you submit a binding offer. The contract is concluded when the payment is confirmed. You will then receive an order confirmation by email.",
  "Mit epischer Beute": "With epic loot",
