  "Mit ihm rief Khar die Stämme. Varra will es zerbrechen.": "With it, Khar called the tribes. Varra wants to break it.",
  "Mit ihm siegelte Ulgrim die Gräber seiner Feinde.": "With it, Ulgrim sealed the graves of his enemies.",
