  "Möge die Glut dich wärmen, Wanderer. Seit der Berg wieder raucht, kommt kaum noch jemand durch die Senke.": "May the embers keep you warm, wanderer. Since the mountain started smoking again, hardly anyone makes it through the hollow.",
