  "Mutter Fäulnis wartet in ihrem Nest am Grund des Sporenschlunds.": "Mother Rot waits in her nest at the bottom of the Spore Hollow.",
  "Mutter Fäulnis. So nennen sie es. Und auf jedem Götzen dieselbe Krone aus Flammen. Varra hatte recht, das ist größer als die Marsch.": "Mother Rot. That's what they call it. And on every idol, the same crown of flames. Varra was right, this is bigger than the marsh.",
