  "Nerith trug ihn, bevor die Flut kam.": "Nerith wore it before the flood came.",
  "Nerith war einst Hohepriesterin. Die Flut hat sie nicht getötet – sie hat sie verwandelt. Geh in den Tempel und bring mir ihre Perle.": "Nerith was once a high priestess. The flood didn't kill her – it changed her. Go into the temple and bring me her pearl.",
