  "Rask besiegt": "Rask defeated",
  "Rask hat drei Dörfer niedergebrannt, bevor der Berg es tat. Er versteckt sich in seinem Lager. Beende das.": "Rask burned three villages before the mountain did. He's hiding in his camp. End it.",
  "Rask ist gefährlich. Achte auf seine Feuerbomben.": "Rask is dangerous. Watch out for his fire bombs.",
  "Rask ist tot? Dann schulde ich dir mehr als Gold. In seinem Zelt lag ein Brief mit einer Flammenkrone als Siegel: Er hat die Dörfer für jemanden am Berg geräumt. Nimm das – es war seine beste Beute.": "Rask is dead? Then I owe you more than gold. In his tent lay a letter sealed with a Flame Crown: he cleared the villages for someone on the mountain. Take this – it was his finest plunder.",
