  "Rauhwacht hält. Solange Leute wie du hier sind.": "Rookwatch holds. As long as people like you are here.",
  "Rauhwacht hält. Solange Leute wie du hier sind. Pass am Aufstieg auf einen Golem auf, der nicht zu den anderen gehört. Asch'rak. Er trägt eine Faust aus Schlacke.": "Rookwatch holds. As long as people like you are here. On the ascent, watch out for a golem that doesn't belong with the others. Asch'rak. He has a fist of slag.",
  "Rauhwacht wird bleiben. Irgendwer muss den Berg im Auge behalten, auch wenn er schweigt.": "Rookwatch will remain. Someone has to keep an eye on the mountain, even when it's silent.",
