  "Ressource": "Resource",
  "Retter der Glutsenke": "Savior of Emberhollow",
  "Riech mal. Nein, besser nicht. Jedes Schwert in Frosthold wird dir danken.": "The War Banners are scattered far across the steppe. Look for the smoke of the watchfires.",
  "Riechst du das? Safran, Zimt, Glutpfeffer. Damit bezahle ich einen Monat Miete am Außenposten. Hier, dein Anteil, und sag keinem, wie viel er ist.": "Smell that? Saffron, cinnamon, ember pepper. That pays a month's rent at the outpost. Here, your share, and don't tell anyone how much it is.",
  "Riechst du das? Salbei, Asche und ein Hauch von Gefahr.": "Smell that? Sage, ash and a hint of danger.",
  "Riechst du das? Salbei, Asche und ein Hauch von Gefahr. Tief im Wald wächst etwas, das die Dornkriecher gebiert. Die Dornenmutter. Ihr Saft wäre ein Vermögen wert.": "Smell that? Sage, ash and a hint of danger. Deep in the forest grows something that births the Thorn Crawlers. The Thorn Mother. Her sap would be worth a fortune.",
  "Riecht nach Salz und altem Weihrauch.": "Smells of salt and old incense.",
  "Riesenknochen-Senke": "Giant's Bone Hollow",
  "Ring": "Ring",
