  "Schneewühler erlegt": "Snow Burrowers slain",
  "Schnelle Dolchkombos mit hoher kritischer Trefferchance. Taucht durch Gegnerreihen und schlägt zu, bevor sie reagieren.": "Fast dagger combos with a high critical strike chance. Slips through enemy lines and strikes before they can react.",
  "Schon bekannt": "Already Known",
  "Schon ein Konto? Anmelden": "Already have an account? Sign In",
  "Schöne Krallen. Scharf, weiß, unversehrt. Die Reichen werden sich darum prügeln. Hier ist dein Anteil, und der ist wirklich ehrlich. Fast.": "Lovely claws. Sharp, white, unblemished. The rich will brawl over these. Here's your share, and it really is honest. Almost.",
  "Schuhe der Kolossglut": "Colossus Fire Slippers",
  "Schuppen aus Magma": "Scales of Magma",
