  "Schuppenhemd der Glutschwinge": "Emberwing Scale Shirt",
  "Schuppenpanzer": "Scale Armor",
  "Schurke": "Rogue",
  "Schütze Ysoldes Ritual, während sie die Spalte endgültig verschließt.": "Protect Ysolde's ritual while she seals the rift for good.",
  "Schutztotems entzündet": "Ward Totems lit",
  "Schwarzes Eisen aus den Tiefen der Katakomben.": "Black iron from the depths of the Catacombs.",
  "Schwarzes Glas, geschliffen zu einer Schneide, die nie stumpf wird.": "Black glass, honed to an edge that never dulls.",
  "Schwer genug, um Knochen zu Staub zu schlagen.": "Heavy enough to beat bone to dust.",
  "Schwer und rot. Genau richtig. Heute Abend brauen wir in einem Kessel ohne Loch.": "Heavy and red. Just right. Tonight we brew in a kettle without a hole.",
  "Schwer, laut und sehr, sehr sicher.": "Heavy, loud and very, very safe.",
  "Schwere Treffer (dritter Kombo-Schlag und Fähigkeiten) heilen 3 % deines maximalen Lebens.": "Heavy hits (third combo strike and skills) heal 3% of your max Health.",
  "Schwert": "Sword",
  "Schwert, Schild und Wut": "Sword, shield and rage",
  "Sechs Drachen. Achte auf ihren Atem.": "Six drakes. Watch out for their breath.",
  "Seelenfeuer": "Soulfire",
  "Seelenlicht": "Soullight",
  "Seelenwolf": "Soul Wolf",
  "Seherin": "Seer",
  "Seherin Ysolde": "Seer Ysolde",
  "Sei gegrüßt.": "Greetings.",
  "Seide für die Esse": "Silk for the Forge",
  "Seidenhandschuhe": "Silk Gloves",
  "Seidenschuhe": "Silk Slippers",
  "Seilaufzug": "Rope Lift",
  "Sein Siegel … Sieh her: unter dem Knochenwappen glüht ein zweites Zeichen, eine Krone aus Flammen. Varkhul hat nicht aus eigenem Willen gerufen. Die Glutsenke steht in deiner Schuld.": "His seal… Look here: beneath the bone crest glows a second sign, a crown of flames. Varkhul did not call them of his own will. Emberhollow is in your debt.",
  "Seine Diener steigen aus der Glut": "His servants rise from the embers",
  "Seit das Moorgrauen tot ist, schlafen meine Wachen wieder. Schnarchen tun sie auch. Man kann nicht alles haben.": "Since the Bog Horror died, my guards sleep again. They snore, too. You can't have everything.",
  "Seit der Ascheregen fällt, kommen die Wölfe bis an die Hütten. Erlege sechs von ihnen, dann trauen sich die anderen nicht mehr her.": "Ever since the ash rain began, the wolves come right up to the huts. Slay six of them, and the others won't dare come near.",
  "Seit die Gewürze zurück sind, riecht der ganze Außenposten nach Glutpfeffer. Die Wachen niesen, aber sie beschweren sich nicht.": "Since the spices came back, the whole outpost smells of ember pepper. The guards sneeze, but they don't complain.",
  "Seit die Totems brennen, kriechen die Seuchenkröten aus dem Nebel an meine Mauer. Ihr Gift frisst den Mörtel. Ich habe Wachen, aber keine, die eine Kröte anfassen wollen. Erschlag zwölf.": "Ever since the totems burned, the Plague Toads have been crawling out of the fog to my wall. Their venom eats the mortar. I have guards, but none willing to touch a toad. Slay twelve.",
  "Seit hundert Jahren geht jedes Jahr ein Pilgerzug zum Schrein am Thronweg. Letztes Jahr kam keiner zurück. Dieses Jahr sind es nur noch sechs. Ich gehe mit ihnen. Komm mit uns, und wir kommen vielleicht an.": "For a hundred years, a procession of pilgrims has walked to the shrine on the Throne Road every year. Last year, none came back. This year there are only six. I'm going with them. Come with us, and perhaps we'll arrive.",
  "Seit Khar gefallen ist, heult das Hügelgrab jede Nacht. Die Nomaden sagen, der Hügelkönig sei erwacht. Geh zum Grabtor im Südosten, steig hinab und erschlag die Toten, die sich dort sammeln.": "Ever since Khar fell, the Barrow howls every night. The nomads say the Barrow King has awakened. Go to the Barrow Gate in the southeast, descend, and slay the dead gathering there.",
  "Seit Rask weg ist, rollen meine Wagen wieder. Für dich gibt es heute keinen Aufschlag. Na gut, einen kleinen.": "Since Rask is gone, my wagons are rolling again. No markup for you today. Fine, a small one.",
  "Seit Wochen reiten Plünderer bis an unsere Palisade. Sie tragen Khars Farben, und Khar trägt die Flammenkrone. Erschlag fünfzehn von ihnen, egal ob mit Klinge oder Bogen. Dann wissen sie, dass hier wieder jemand kämpft.": "For weeks now, Raiders have been riding right up to our palisade. They wear Khar's colors, and Khar wears the Flame Crown. Slay fifteen of them, blade or bow, it makes no difference. Then they'll know someone is fighting here again.",
  "Selbst in der Asche wächst noch etwas Heilsames, Kindchen.": "Even in the ash something healing still grows, child.",
  "Selten": "Rare",
  "Selten und begehrt. In ihm schläft alte Magie.": "Rare and coveted. Old magic sleeps within.",
  "Selten vom Frostwurm in den Reifhöhlen": "Rare drop from the Frost Wyrm in the Rime Caverns",
  "Selten vom Hügelkönig im Heulenden Hügelgrab": "Rare drop from the Barrow King in the Howling Barrow",
  "Selten vom Moorgrauen in der Faulmarsch": "Rare drop from the Bog Horror in the Blighted Marsh",
  "Selten von Mutter Fäulnis im Sporenschlund": "Rare drop from Mother Rot in the Spore Hollow",
  "Seltener Fang": "Rare Catch",
  "Seltener Gegner besiegt": "Rare enemy defeated",
  "Seltenheit erkennst du am Rahmen: grün, blau, lila, orange.": "You can tell rarity by the frame: green, blue, purple, orange.",
  "Selvara": "Selvara",
  "Seraphel": "Seraphel",
