  "SHA-256": "SHA-256",
  "Shop": "Shop",
  "Sie brennen schlecht. Wie alles, was mit Angst geschrieben wurde. Aber sie brennen.": "They burn poorly. Like everything written in fear. But they burn.",
  "Sie haben mehr Asche gesehen als jeder Soldat.": "They have seen more ash than any soldier.",
  "Sie hinterlassen im Schnee keine Spuren.": "They leave no tracks in the snow.",
  "Sie klingt, wenn man sie zupft. Wie Glas. Das ist die beste Seide, die ich je gesehen habe.": "It rings when you pluck it. Like glass. That's the finest silk I've ever seen.",
  "Sie pochen noch. Unheimlich. Aber sie halten die Hitze. Hier, für deine Mühe – aus meinem persönlichen Vorrat.": "They're still throbbing. Eerie. But they hold the heat. Here, for your trouble – from my personal stock.",
  "Sie pulsieren noch! Perfekt. Mit etwas Glück kann bald niemand mehr an diesen Viechern sterben.": "They're still pulsing! Perfect. With a little luck, soon no one will die from these beasts again.",
  "Sie pulsiert noch. Nicht anfassen, wenn es geht.": "It still pulses. Don't touch it if you can help it.",
  "Sie ruhen jetzt. Ich werde ihre Namen in den Stein über dem Tor schlagen. Deinen auch, wenn du willst.": "They rest now. I'll carve their names into the stone above the gate. Yours too, if you like.",
  "Sie schmelzen nicht einmal im Feuer. Ich werfe sie in die Schlucht. Soll sich das Eis darum kümmern.": "They don't even melt in the fire. I'll throw them into the gorge. Let the ice deal with them.",
  "Sie schreibt von selbst weiter, wenn man sie loslässt.": "It keeps writing on its own when you let go.",
  "Sie sind kalt. Kälter als Stein. Heute Nacht singen wir für sie. Danke, Fremder.": "They're cold. Colder than stone. Tonight we sing for them. Thank you, stranger.",
  "Sieg!": "Victory!",
  "Siegel der Adepten": "Sigils of the Adepts",
  "Siegel der Asche": "Seal of Ash",
  "Siegel der Asche erneuern": "Renew the Seal of Ash",
  "Siegel der Glut": "Seal of Ember",
  "Siegel der Glut erneuern": "Renew the Seal of Ember",
  "Siegel des Aschenfürsten": "Ash Sovereign's Seal",
  "Siegel des Feuers": "Seal of Fire",
  "Siegel des Feuers erneuern": "Renew the Seal of Fire",
  "Siegel erneuern": "Renew seal",
  "Siegel erneuert": "Seals renewed",
  "Siegel in der alten Folge erneuert (Asche, Glut, Feuer)": "Seals renewed in the old order (Ash, Ember, Fire)",
  "Siegelring des Hügelkönigs": "Barrow King's Signet",
  "Siehst du? Ein Händler zahlt seine Schulden. Meistens.": "See? A merchant pays his debts. Usually.",
  "Sigrun": "Sigrun",
  "Sigrun jagt jeden Tag. Jag mit.": "Sigrun hunts every day. Hunt with her.",
  "Sigruns Jagdhütte": "Sigrun's Hunting Lodge",
  "Silberamulett": "Silver Amulet",
  "Silberdorn": "Silverthorn",
  "Silberne Zeichen laufen um den Saum.": "Silver sigils run around the hem.",
  "Silberring": "Silver Ring",
  "Skalvyr getötet": "Skalvyr slain",
  "Skalvyr lässt Eiswände aus dem Boden brechen": "Skalvyr makes walls of ice burst from the ground",
  "Skalvyr, der Frostwurm": "Skalvyr, the Frost Wyrm",
  "Skalvyr, der Frostwurm (Reifhöhlen)": "Skalvyr, the Frost Wyrm (Rime Caverns)",
  "Skalvyr. Die Hexen singen seinen Namen. Er war einmal der Wächter dieser Berge, bevor die Krone ihn zu ihrem Diener machte. Erlöse ihn. Und bring mir sein Herz, damit Frosthold weiß, dass der Winter vorbei ist.": "Skalvyr. The witches sing his name. He was once the guardian of these mountains, before the Crown made him its servant. Set him free. And bring me his heart, so Frosthold knows the winter is over.",
  "Skalvyrs Fang": "Skalvyr's Fang",
  "Skalvyrs Hort liegt am Grund der Reifhöhlen.": "Skalvyr's lair lies at the bottom of the Rime Caverns.",
  "Skarvi": "Skarvi",
  "Skelettkrieger": "Skeleton Warrior",
  "Skelettkrieger zerschlagen": "Skeleton Warriors shattered",
  "Skelettschütze": "Skeleton Archer",
  "Slice {0} doppelt definiert": "Slice {0} doppelt definiert",
  "Slice {0} unbekannt": "Slice {0} unbekannt",
  "Smaragdring": "Emerald Ring",
  "So beginnt dein Held": "How your hero begins",
  "So kann dein Held mit besserer Beute aussehen": "How your hero can look with better loot",
  "So lang wie ein Finger und noch immer scharf.": "As long as a finger and still sharp.",
  "So lang wie ein Unterarm. Beweis genug für jeden Jarl.": "As long as a forearm. Proof enough for any Jarl.",
  "So viel Salz! Das reicht für hundert Verbände. Danke dir.": "So much salt! That's enough for a hundred bandages. Thank you.",
  "Sold ist Sold. Du hast ihn dir verdient.": "A wage is a wage. You've earned it.",
  "Soldatenschwert": "Soldier's Sword",
  "Söldner": "Mercenary",
  "Sollten wir Emberwrath einstellen, kündigen wir das mindestens drei Monate vorher an und verkaufen ab der Ankündigung nichts mehr. Hast du in den letzten drei Monaten vor der Ankündigung etwas gekauft, erstatten wir dir dafür den Kaufpreis.": "Should we discontinue Emberwrath, we will announce this at least three months in advance and stop all sales from the announcement onward. If you made a purchase in the three months before the announcement, we will refund the purchase price to you.",
  "Sonnenamulett": "Sun Amulet",
  "Sonnenhammer": "Sunhammer",
  "Sonnenscheibe der Steppe": "Sun Disc of the Steppe",
  "Sorry": "Sorry",
