  "Spam oder Werbung": "Spam or advertising",
  "speichern": "save",
  "Speichern nicht möglich – der Browser blockiert den Speicher.": "Can't save – the browser is blocking storage.",
  "Speicherplätze": "Save Slots",
  "Speicherplätze · {0}": "Save Slots · {0}",
  "Speichert und kehrt zum Titelbildschirm zurück": "Saves and returns to the title screen",
  "Sperre aufheben": "Lift Ban",
  "Sperrfeuer": "Barrage",
  "Spielen": "Play",
  "Spielen ab {0} Jahren; unter {1} nur mit Zustimmung der Eltern.": "Ages {0}+; under {1} only with parental consent.",
  "Spielen ist kostenlos, im Browser, ohne Download und ohne Installation. Im": "Playing is free, in your browser, with no download and no installation. In the",
  "Spielen ist kostenlos, im Browser, ohne Download und ohne Installation. Im <a href=\"shop\">Shop</a> kannst du freiwillig Gold und Designs kaufen. Alles, was du zum Spielen brauchst, erspielst du auch ohne Kauf.": "Playing is free, in your browser, with no download and no installation. In the <a href=\"shop\">Shop</a>, you can optionally buy Gold and cosmetics. Everything you need to play can also be earned without buying anything.",
  "Spielen ist kostenlos. Im Shop kannst du freiwillig Gold und Designs kaufen; alles, was du zum Spielen brauchst, kannst du auch ohne Kauf erspielen. Wir arbeiten ständig am Spiel, deshalb ändern sich Inhalte, Regeln und Werte. Für Wartung und Updates kann das Spiel zeitweise nicht erreichbar sein. Einen Anspruch auf eine bestimmte Verfügbarkeit oder auf bestimmte Inhalte gibt es nicht.": "Playing is free. In the Shop, you can optionally buy Gold and cosmetics; everything you need to play can also be earned without buying anything. We are constantly working on the game, so content, rules and values change. The game may be temporarily unavailable for maintenance and updates. There is no entitlement to any particular availability or to any particular content.",
