  "Thane": "Thane",
  "Thane hat vom verbrannten Rezept gehört und hat einen Auftrag für jemanden, dem er traut.": "Thane has heard about the burned recipe and has a job for someone he trusts.",
  "Thane ist ein sturer Hund, aber er hält die Mirefeste seit zwanzig Jahren. Wenn jemand weiß, was in der Marsch vor sich geht, dann er. Nimm den Weg nach Osten zum Marschrand.": "Thane is a stubborn dog, but he's held Mirekeep for twenty years. If anyone knows what's going on in the Marsh, it's him. Take the road east to Marsh's Edge.",
  "Thane lebt noch? Dieser alte Moorhund. Gut. Setz dich ans Feuer, Fremder. Hier oben erfriert man schneller, als man stirbt.": "Thane's still alive? That old bog hound. Good. Sit by the fire, stranger. Up here you freeze faster than you die.",
