  "Tränke, Verbände, Stiefel ohne Löcher. Was darf es sein?": "Potions, bandages, boots without holes. What'll it be?",
  "Tränke, Verbände, Stiefel ohne Löcher. Was darf es sein? Hier in der Marsch ist alles teuer, besonders das Überleben.": "Potions, bandages, boots without holes. What'll it be? Here in the Marsh everything is expensive, especially survival.",
