  "Übernimm sie in dein Konto, dann sind sie in der Cloud gesichert und auf jedem Gerät spielbar.": "Move them to your account to back them up in the cloud and play them on any device.",
  "Übernommen": "Transferred",
  "Überquere den Frostpass und melde dich bei Jarl Eskil in Frosthold.": "Cross the Frost Pass and report to Jarl Eskil in Frosthold.",
  "Über­schreiben": "Over­write",
  "Übersicht": "Overview",
  "Ufer des Tempels erreicht": "Temple shore reached",
  "Ulgrim besiegt": "Ulgrim defeated",
  "Ulgrim war vor tausend Jahren König der Steppe. Jemand hat ihn geweckt. Geh in die tiefste Kammer des Hügelgrabs, leg ihn zurück in sein Grab und bring mir sein Siegel. Ich muss wissen, wer ihn gerufen hat.": "Ulgrim was King of the Steppe a thousand years ago. Someone woke him. Go to the deepest chamber of the Barrow, lay him back in his grave, and bring me his seal. I need to know who called him.",
  "Ulgrim wartet in der Grabkammer am Ende des Hügelgrabs.": "Ulgrim waits in the burial chamber at the end of the Barrow.",
  "Ulgrim wurde darin begraben. Er hat ihn nie abgelegt.": "Ulgrim was buried in it. He never took it off.",
  "Ulgrim, der Hügelkönig": "Ulgrim, the Barrow King",
  "Ulgrim, der Hügelkönig (Heulendes Hügelgrab)": "Ulgrim, the Barrow King (Howling Barrow)",
  "Ulgrims Grabklinge": "Ulgrim's Barrow Blade",
  "Um dein Widerrufsrecht auszuüben, musst du uns (Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Deutschland, E&#8209;Mail support@emberwrath.com) mittels einer eindeutigen Erklärung (zum Beispiel eine E&#8209;Mail oder ein mit der Post versandter Brief) über deinen Entschluss, diesen Vertrag zu widerrufen, informieren. Du kannst dafür das unten stehende Muster-Widerrufsformular verwenden, das jedoch nicht vorgeschrieben ist.": "To exercise the right of withdrawal, you must inform us (Dominic Paul Kroll, Friedenstraße 5, 14532 Stahnsdorf, Germany, email support@emberwrath.com) of your decision to withdraw from this contract by an unequivocal statement (e.g. an email or a letter sent by post). You may use the model withdrawal form below, but it is not obligatory.",
  "Unbekannt": "Unknown",
  "Unbekannter Dungeon.": "Unknown dungeon.",
