  "Unbeugsam": "Unbroken",
  "Unbeugsam! Du bleibst stehen.": "Unbroken! You stay on your feet.",
  "und dann auf": "and then",
  "Unerschütterlich": "Unshakable",
  "Ungewöhnlich": "Uncommon",
  "Unsere Pfeile fliegen krumm, seit die Plünderer unsere Vorräte verbrannt haben. Die Aschegeier kreisen über jedem Schlachtfeld. Hol mir acht ihrer Federn, dann fliegen unsere Pfeile wieder gerade.": "Our arrows fly crooked ever since the raiders burned our supplies. The Ash Vultures circle over every battlefield. Bring me eight of their feathers, and our arrows will fly true again.",
  "Unten am Damm, dann an der Brücke, zuletzt oben am Wasserfall.": "Down at the dam, then at the bridge, last up at the falls.",
  "unter 1 Min.": "under 1 min",
  "Unter 18? Kaufe nur mit Erlaubnis deiner Eltern.": "Under 18? Only buy with your parents' permission.",
  "Unter dem Schnee": "Beneath the Snow",
  "Unter dem umgestürzten Turm und am Bach.": "Under the fallen tower and by the stream.",
  "Unter den Bäumen friert keiner mehr von innen. Nur noch von außen. Dagegen habe ich Mäntel.": "Under the trees no one freezes from the inside anymore. Only from the outside. For that, I have cloaks.",
  "Unter der Glutsenke": "Beneath Emberhollow",
  "Unterschreib hier. Und hier. Dann reden wir über Ausrüstung.": "Sign here. And here. Then we'll talk gear.",
  "Unterschrift des/der Verbraucher(s) (nur bei Mitteilung auf Papier):": "Signature of consumer(s) (only if this form is notified on paper):",
  "Unzerbrechlich": "Unbreakable",
  "url({0})": "url({0})",
  "V / 6": "V / 6",
  "Vaelis": "Vaelis",
  "Varkhul": "Varkhul",
  "Varkhul besiegt": "Varkhul defeated",
  "Varkhul rast vor Zorn": "Varkhul rages",
  "Varkhul ruft die Toten": "Varkhul calls forth the dead",
  "Varkhul war nur ein Diener. Im Osten, hinter dem Aschenwald, glüht der Berg heller als je zuvor. Wächterin Ilsa hält dort das Lager. Geh zu ihr – sie wird dich brauchen.": "Varkhul was only a servant. In the east, beyond the Ashwood, the mountain glows brighter than ever before. Warden Ilsa holds the camp there. Go to her – she will need you.",
  "Varkhul wartet in der großen Halle. Geh nicht unvorbereitet.": "Varkhul waits in the great hall. Don't go unprepared.",
  "Varkhul, der Knochenfürst": "Varkhul, the Bone Lord",
  "Varkhul. So hieß der Fürst, der hier vor dreihundert Jahren begraben wurde. Er ruft die Toten. Solange er steht, finden sie keine Ruhe. Bring mir sein Siegel.": "Varkhul. That was the name of the lord buried here three hundred years ago. He calls the dead. As long as he stands, they will find no rest. Bring me his seal.",
  "Varkhuls Schlächterbeil": "Varkhul's Butcher Cleaver",
  "Varkhuls Siegel": "Varkhul's Seal",
  "Varra": "Varra",
  "Varra schickt mir einen Helden? Hier sterben Helden schneller als Mücken. Aber gut. Komm rein, bevor der Nebel dich frisst.": "Varra sends me a hero? Heroes die faster than gnats out here. Fine, then. Come inside before the mist eats you.",
  "Vendria": "Vendria",
