  "Verliehen jenen, die die Glutprüfungen überstehen.": "Bestowed on those who survive the Ember Trials.",
  "Verlorene Karawane gefunden": "Lost Caravan found",
  "Vernichte die Aschengeister, die die Bastion umkreisen.": "Destroy the Ash Wraiths circling the Bastion.",
  "Vernichte die Feuerkobolde, die Rauhwacht belagern.": "Destroy the Fire Imps besieging Rookwatch.",
  "Vernichte Mutter Fäulnis im Herzen des Sporenschlunds.": "Destroy Mother Rot in the heart of the Spore Hollow.",
