  "Verteidige Ysolde, bis das Ritual vollendet ist.": "Defend Ysolde until the ritual is complete.",
  "Verteidiger": "Defender",
  "Vertiefung": "Expertise",
  "Vertragssprache ist Deutsch. Den Vertragstext speichern wir nicht zum Abruf für dich. Du bekommst ihn aber mit der Bestellbestätigung per E&#8209;Mail, und diese Bedingungen stehen jederzeit unter www.emberwrath.com/kaufbedingungen.": "The contract language is German. We do not store the contract text for you to retrieve. However, you receive it with the order confirmation by email, and these terms are available at any time at www.emberwrath.com/kaufbedingungen.",
  "Vertreibe die Aschegeier, die Imras Karawanen bis zum Außenposten folgen.": "Drive off the Ash Vultures that follow Imra's caravans all the way to the outpost.",
  "Vertreibe die Aschewölfe, die die Glutsenke heimsuchen.": "Drive off the Ash Wolves plaguing Emberhollow.",
  "Vertreibe die Klippenharpyien und zerstöre ihre Nester.": "Drive off the Cliff Harpies and destroy their nests.",
  "Verwaltung": "Administration",
  "Verwaltung öffnen": "Open Administration",
