  "Verzauberer": "Enchanter",
  "Verzaubern": "Enchant",
  "Vesk": "Vesk",
  "Vesk bleibt dir etwas schuldig. Ilsa ist enttäuscht.": "Vesk owes you one. Ilsa is disappointed.",
  "Vesk der Wache übergeben": "Hand Vesk over to the Watch",
  "Vesk eine Chance geben": "Give Vesk a chance",
  "Vesk muss die gestohlene Ware der Wache zurückkaufen. Hilf ihm, die Kisten zu finden.": "Vesk must buy back the Watch's stolen goods. Help him find the crates.",
  "Vesk will seine Schuld begleichen: Er weiß, wo die Banditen ihre Beute vergraben haben.": "Vesk wants to repay his debt: he knows where the bandits buried their loot.",
  "Vesk zahlt für jede Bedrohung weniger im Aschenwald.": "Vesk pays for every threat removed from the Ashwood.",
  "Vesk, der Händler": "Vesk, the Merchant",
  "Vesks Karren": "Vesk's Cart",
  "Vesks Wagen": "Vesk's Wagon",
  "Veyla": "Veyla",
  "Vhara": "Vhara",
  "Viel Glück": "Good luck",
  "Viele Pilger kamen vor mir. Keiner kam an. Die Aschengeister tragen noch ihre Reliquien. Bring mir sechs, damit ich sie am Thron niederlegen kann, für jene, die es nicht geschafft haben.": "Many pilgrims came before me. None arrived. The Ash Wraiths still carry their relics. Bring me six, so I can lay them at the Throne for those who never made it.",
  "Vielseitig und zäh": "Versatile and tough",
  "Vier Glutkerne. Ohne die bleibt jede Ramme Brennholz.": "Four Ember Cores. Without them, every ram is just firewood.",
  "Vier Kisten mit Vesks Waffen liegen im Wald.": "Four crates of Vesk's weapons lie in the woods.",
  "Vier Kisten. Ilsa redet wieder mit mir. Fast freundlich. Hier, das ist kein Bestechungsgeld. Das ist ein Dank.": "Four crates. Ilsa's talking to me again. Almost friendly. Here, this isn't a bribe. It's a thank-you.",
  "Violettes Feuer kriecht über die Klinge des Knochenfürsten.": "Violet fire creeps along the Bone Lord's blade.",
  "Volk": "Race",
  "voll": "full",
  "Voll gerüstet": "Fully Armed",
