  "Vollbild auf dem iPhone": "Full screen on iPhone",
  "Vollbild beenden": "Exit Fullscreen",
  "Vollständig": "Complete",
  "Von den Magmaschlangen der Glutöde. Heiß genug, um Holz zu entzünden.": "From the Magma Serpents of the Ember Wastes. Hot enough to set wood alight.",
  "vor {0} Min.": "{0} min ago",
  "vor {0} Std.": "{0} h ago",
  "vor {0} Tagen": "{0} days ago",
  "Vor dem Thron": "Before the Throne",
  "Vor der Thronhalle steht ein letzter Wächter. Meine Späher sagen, er war einmal ein König wie Ulgrim. Jetzt ist er nur noch Glut und Rüstung. Besiege ihn, dann steht nur noch Malgareth zwischen dir und dem Ende.": "Before the Throne Hall stands one last guardian. My scouts say he was once a king, like Ulgrim. Now he's nothing but embers and armor. Defeat him, and only Malgareth will stand between you and the end.",
  "Vor Ignaroths Thron steht ein Wächter aus lebendem Eisen. Niemand kommt an ihm vorbei. Bis heute.": "Before Ignaroth's throne stands a warden of living iron. No one gets past him. Until today.",
  "Vor jedem Spielstart wird der vorherige Stand automatisch gesichert.": "Your previous progress is saved automatically each time you start playing.",
