  "Warm wie ein Herdstein. Brom kann damit Waffen veredeln.": "Warm as a hearthstone. Brom can use it to refine weapons.",
  "Warme Sachen und heiße Tränke. Mehr braucht man hier oben nicht.": "Warm clothes and hot potions. That's all you need up here.",
  "Warme Sachen und heiße Tränke. Mehr braucht man hier oben nicht. Außer Mut. Den verkaufe ich nicht.": "Warm clothes and hot potions. That's all you need up here. Except courage. That, I don't sell.",
  "Wärmt wie ein Sommermorgen, selbst in den tiefsten Grüften.": "Warm as a summer morning, even in the deepest crypts.",
  "Warte auf die anderen …": "Waiting for the others …",
  "wartet": "waiting",
  "Was die Bastion hat, hast du. Gegen Gold natürlich.": "Whatever the Bastion has, you can have. For gold, of course.",
  "Was die Bastion hat, hast du. Gegen Gold natürlich. Gold hält die Mauern nicht, aber es hält die Leute auf den Mauern.": "Whatever the Bastion has, you can have. For gold, of course. Gold doesn't hold the walls, but it holds the people on them.",
  "Was die Steppe nicht frisst, verkaufe ich.": "Whatever the Steppe doesn't devour, I sell.",
  "Was ein Angebot genau enthält und was es kostet, steht im Shop und auf der Bezahlseite. Gekaufte Inhalte sind eine Nutzungsberechtigung im Spiel. Sie haben außerhalb des Spiels keinen Geldwert, werden nicht in Geld zurückgetauscht und dürfen nicht weiterverkauft werden.": "Exactly what an offer includes and what it costs is shown in the Shop and on the checkout page. Purchased content is a license to use it in the game. It has no monetary value outside the game, cannot be exchanged back for money and may not be resold.",
  "Was im Wasser lauert": "What Lurks in the Water",
  "Was ist passiert?": "What happened?",
  "Was ist passiert? (freiwillig, bei „Etwas anderes“ nötig)": "What happened? (optional, required for “Something else”)",
  "Was krank macht, kann auch heilen, wenn man es richtig braut. Die Pilze im Sporenschlund sind die Quelle der Fäulnis. Bring mir sechs Sporenkappen, und ich mache daraus etwas, das die Marsch heilt.": "What sickens can also heal, if you brew it right. The mushrooms in the Spore Hollow are the source of the rot. Bring me six Spore Caps, and I'll make something from them that heals the marsh.",
  "Was sie greifen, beginnt zu schmelzen.": "Whatever they grip begins to melt.",
  "Was sie greifen, zerfällt zu Asche.": "Whatever they grip crumbles to ash.",
  "WASD / Pfeile": "WASD / Arrows",
  "Wasser aus der Quelle der Ahnen. Kesh sagt, es ist heilig.": "Water from the Spring of the Ancestors. Kesh says it is sacred.",
  "Wasser für die Ahnen": "Water for the Ancestors",
  "Wasser perlt darauf, auch wenn es trocken ist.": "Water beads on it, even when it is dry.",
  "Wechsle in Welt {0} …": "Switching to World {0} …",
  "Weg wird gezeigt": "Showing the way",
  "Weg zur verfolgten Quest": "Path to the tracked quest",
