  "Wegstein von {0} entdeckt": "Waystone of {0} discovered",
  "Wegweiser lesen": "Read signpost",
  "Wegwerfen": "Discard",
  "Weiche seinem Ansturm aus": "Dodge his charge",
  "Weiß ich auch nicht genau": "Not sure either",
  "Weiß wie frischer Schnee und doppelt so dicht.": "White as fresh snow and twice as thick.",
  "Weiß, gebogen und scharf wie ein Messer.": "White, curved and sharp as a knife.",
  "Weiße": "White",
  "Weiße + Grüne": "White + Green",
  "Weiße verkaufen · {0}": "Sell white · {0}",
  "Weiße Laterne": "White Lantern",
  "Weiße Laterne am Grab entzünden": "Light the white lantern at the grave",
  "Weiße verkaufen · {0} (+{1})": "Sell White · {0} (+{1})",
  "Weißt du, was eine Schneepirscherkralle im Süden kostet? Ich auch nicht genau, aber viel. Die Reichen hängen sie sich um den Hals. Bring mir sechs, dann teilen wir den Gewinn. Ehrlich.": "Do you know what a Snowstalker claw fetches in the south? Neither do I, not exactly, but a lot. The rich hang them around their necks. Bring me six, and we'll split the profit. Honest.",
  "Weiter …": "Continuing …",
  "Weiter gehts": "Let's keep going",
  "Weiter im Norden lag ein Dorf. Dann kam die Fäulnis und das Dorf sank. Die Kröten dort speien Gift, die Egel saugen alles aus, was noch lebt. Geh hin und räum auf. Fünfzehn von dem Viehzeug.": "Further north there was a village. Then the rot came and the village sank. The toads there spit poison, and the leeches suck dry anything still alive. Go and clean it out. Fifteen of the vermin.",
  "Weiter mit Google": "Continue with Google",
  "weiter?": "next?",
  "Weiter?": "Move on?",
  "Weitere laden": "Load More",
  "Weiterspielen": "Keep Playing",
  "Weizenblond": "Wheat Blond",
  "Welt": "World",
  "Welt {0}": "World {0}",
  "Welt {0} · {1} Spieler": "World {0} · {1} players",
