  "Welt-Server nicht erreichbar": "World server unreachable",
  "Welten": "Worlds",
  "Weltenbrand": "Worldfire",
  "Wenig Mana": "Low mana",
  "Weniger Gold, aber Thane erfährt davon.": "Less gold, but Thane hears of it.",
  "Wenn du den Vertrag widerrufen willst, fülle bitte dieses Formular aus und sende es zurück.": "If you wish to withdraw from the contract, please complete and return this form.",
  "Wenn du dich für den Newsletter anmeldest, speichern wir deine E&#8209;Mail-Adresse, den Zeitpunkt der Anmeldung und den Zeitpunkt deiner Bestätigung. Du bekommst zuerst eine E&#8209;Mail mit einem Bestätigungslink (Double-Opt-in). Erst nach dem Klick darauf schicken wir dir Neuigkeiten. Unbestätigte Anmeldungen löschen wir nach 7 Tagen. Rechtsgrundlage ist deine Einwilligung (Art. 6 Abs. 1 lit. a DSGVO). Den Newsletter kannst du ab 16 Jahren selbst bestellen; bist du jünger, brauchst du dafür die Einwilligung deiner Eltern (Art. 8 DSGVO).": "If you subscribe to the newsletter, we store your email address, the time you subscribed and the time of your confirmation. You will first receive an email with a confirmation link (double opt-in). Only after you click it will we send you news. We delete unconfirmed subscriptions after 7 days. The legal basis is your consent (Art. 6(1)(a) GDPR). You can subscribe to the newsletter yourself from the age of 16; if you are younger, you need your parents’ consent (Art. 8 GDPR).",
  "Wenn du diesen Vertrag widerrufst, haben wir dir alle Zahlungen, die wir von dir erhalten haben, unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurückzuzahlen, an dem die Mitteilung über deinen Widerruf dieses Vertrags bei uns eingegangen ist. Für diese Rückzahlung verwenden wir dasselbe Zahlungsmittel, das du bei der ursprünglichen Transaktion eingesetzt hast, es sei denn, mit dir wurde ausdrücklich etwas anderes vereinbart; in keinem Fall werden dir wegen dieser Rückzahlung Entgelte berechnet.": "If you withdraw from this contract, we shall reimburse to you all payments received from you without undue delay and in any event not later than fourteen days from the day on which we are informed about your decision to withdraw from this contract. We will carry out such reimbursement using the same means of payment as you used for the initial transaction, unless you have expressly agreed otherwise; in any event, you will not incur any fees as a result of such reimbursement.",
  "Wer sie schwingt, hört den Steppenwind heulen.": "Whoever swings it hears the steppe wind howl.",
  "Wer sie trägt, hinterlässt keine Spuren.": "Whoever wears them leaves no tracks.",
  "Wert: ": "Value: ",
  "Werte": "Stats",
  "Weste des Nachtpirschers": "Nightstalker's Vest",
