  "Westwärts zur Glutsenke": "West to Emberhollow",
  "Westweide": "West Pasture",
  "Widerrufsbelehrung": "Cancellation Policy",
  "Widerrufsrecht": "Right of Withdrawal",
  "Wie abgemacht. Komm wieder, wenn sie wieder heulen.": "As agreed. Come back when they're howling again.",
  "Wieder da": "I'm back",
  "Wieder die Flammenkrone. Varkhul, Khar, jetzt Ulgrim. Alle tragen dasselbe Zeichen. Die Spur führt nach Osten, in die Faulmarsch. Dort hält Wächter Thane die Mirefeste.": "The Flame Crown again. Varkhul, Khar, now Ulgrim. They all bear the same mark. The trail leads east, into the Blighted Marsh. Warden Thane holds Mirekeep there.",
  "Wieder öffnen": "Reopen",
  "Wiederbeleben": "Revive",
  "Wiedergänger im Hügelgrab besiegt": "Revenants in the Barrow defeated",
  "Wildererversteck": "Poachers' Hideout",
