  "Willkommen, {0}! Bevor du spielst, bestätige bitte einmal die Nutzungsbedingungen.": "Welcome, {0}! Before you play, please accept the Terms of Use once.",
  "Willst du keine E‑Mails mehr von uns bekommen?": "Don't want any more emails from us?",
  "Windläufer": "Windrunner",
  "Windows": "Windows",
  "Windschritt": "Windstride",
  "Winterflüstern": "Winterwhisper",
  "Winterjagd": "Winter Hunt",
  "wipe :(": "wipe :(",
  "Wir folgen dir": "We'll follow you",
  "Wir haften unbeschränkt bei Vorsatz und grober Fahrlässigkeit, bei Verletzung von Leben, Körper oder Gesundheit sowie nach dem Produkthaftungsgesetz. Bei leichter Fahrlässigkeit haften wir nur für die Verletzung wesentlicher Pflichten und nur für den typischen, vorhersehbaren Schaden. Wesentlich sind Pflichten, ohne die das Spiel nicht ordnungsgemäß angeboten werden kann und auf deren Einhaltung du dich regelmäßig verlassen darfst. Im Übrigen ist die Haftung ausgeschlossen.": "We are liable without limitation for intent and gross negligence, for injury to life, body or health, and under the Produkthaftungsgesetz (German Product Liability Act). In the case of slight negligence, we are liable only for breaches of material obligations and only for typical, foreseeable damage. Material obligations are those without which the game cannot be properly offered and on whose fulfillment you may regularly rely. Otherwise, liability is excluded.",
  "wir machen das": "we got this",
  "Wir schicken dir einen Link zum Zurücksetzen": "We'll send you a reset link",
  "Wir sind da. Der Schrein ist kalt, aber wir haben ihn gefunden. Wer es nicht geschafft hat, für den beten wir zuerst. Danke.": "We're here. The shrine is cold, but we found it. We'll pray first for those who didn't make it. Thank you.",
  "Wir speichern deine E-Mail, deinen Spielernamen und deine Spielstände, um dein Konto zu betreiben. Du kannst dein Konto jederzeit selbst löschen. Mehr dazu in der ": "We store your email, your player name and your saves to run your account. You can delete your account yourself at any time. Learn more in the ",
  "Wir speichern deine E-Mail, deinen Spielernamen und deine Spielstände, um dein Konto zu betreiben. Du kannst dein Konto jederzeit selbst löschen. Mehr dazu steht in der Datenschutzerklärung.": "We store your email, your player name and your saves to run your account. You can delete your account yourself at any time. Learn more in the Privacy Policy.",
  "Wirbelsturm": "Whirlwind",
  "Wirbelsturm Rang 2: größerer Kreis, eine dritte Klinge und eine Glutwelle. +20 % Schaden.": "Whirlwind Rank 2: a wider circle, a third blade and a wave of embers. +20% damage.",
  "Wirbelsturm und Erdspalter: +12 % Schaden je Rang.": "Whirlwind and Earthshatter: +12% damage per rank.",
  "wird auf Stufe {0} freigeschaltet": "unlocks at Level {0}",
  "Wird eine Zahlung erstattet, zurückgebucht oder angefochten, entfallen die gekauften Inhalte. Wir ziehen dann das gekaufte Gold vom Charakter ab, auch wenn der Kontostand dadurch unter null fällt, und entfernen gekaufte Designs. Bei einer Rückbuchung über die Bank oder das Kartenunternehmen sperren wir weitere Käufe für das Konto, bis der Fall geklärt ist. Melde dich am besten zuerst beim Support, dann lässt sich fast alles ohne Rückbuchung lösen.": "If a payment is refunded, charged back or disputed, the purchased content is forfeited. We will then deduct the purchased Gold from the character, even if this makes the balance fall below zero, and remove purchased cosmetics. In the event of a chargeback via the bank or card issuer, we block further purchases for the account until the case is resolved. It’s best to contact Support first; almost anything can then be resolved without a chargeback.",
