  "Zum Spielen brauchst du ein Emberwrath-Konto": "You need an Emberwrath account to play",
  "Zum Spielen brauchst du ein Konto. Bei der Registrierung verarbeiten wir deine E&#8209;Mail-Adresse, dein Passwort (nur als Hash gespeichert, also als nicht umkehrbarer Prüfwert, nie im Klartext), deinen Anzeigenamen, deine Zustimmung zu den <a href=\"nutzungsbedingungen\">Nutzungsbedingungen</a> (welche Fassung, wann und wo zugestimmt wurde, als Nachweis) sowie Zeitpunkt der Registrierung und der letzten Anmeldung. Zu deinen Charakteren speichern wir Name, Volk, Klasse, Stufe, Gebiet und den Spielstand, damit du auf jedem Gerät weiterspielen kannst. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (Bereitstellung des Spiels, das du nutzen möchtest).": "You need an account to play. When you register, we process your email address, your password (stored only as a hash, i.e. a non-reversible check value, never in plain text), your display name, your acceptance of the <a href=\"nutzungsbedingungen\">Terms of Use</a> (which version, when and where you accepted, as proof) and the time of registration and of your last sign-in. For your characters, we store their name, race, class, level, zone and game progress so that you can continue playing on any device. The legal basis is Art. 6(1)(b) GDPR (provision of the game you wish to use).",
  "Zum Titel": "Title Screen",
  "Zur Glutsenke hinaufsteigen": "Climb up to Emberhollow",
  "Zur Wahrung der Widerrufsfrist reicht es aus, dass du die Mitteilung über die Ausübung des Widerrufsrechts vor Ablauf der Widerrufsfrist absendest.": "To meet the withdrawal deadline, it is sufficient for you to send your communication concerning your exercise of the right of withdrawal before the withdrawal period has expired.",
